/* Novas trilhas de conhecimentos gerais: explicações antes de qualquer exercício. */
const GENERAL_STEP=(id,title,map,speech,explain,observe,term,meaning,remember,visual)=>({...STEP(id,title,map,speech,explain,observe,term,meaning,remember),visual});
JOURNEYS.push(
 {id:'port_texto',name:'Entender textos',label:'Português desde o começo',color:'#af5e79',light:'#fae8ee',symbol:'plan',hero:'Um texto deixa pistas.',description:'Lia aprende a encontrar o assunto, a ideia e as pistas que o próprio texto oferece.',root:['Entender textos','ler, conectar e conferir'],steps:[
  GENERAL_STEP('palavras','A leitura começa com o que está escrito.','O texto','Na placa da biblioteca está escrito: “Aberta de segunda a sexta, das 9h às 17h”.','Um texto transmite informações. Antes de concluir algo, observe quem fala, o assunto e as palavras usadas.','A placa informa os dias e os horários. Ela não afirma que a biblioteca abre no sábado.','Informação explícita','Uma informação expressa diretamente nas palavras ou nos elementos do texto.','Primeiro, procure no texto a informação que sustenta a ideia.',['BIBLIOTECA','segunda a sexta','9h às 17h']),
  GENERAL_STEP('tema','O tema é o assunto de que se fala.','O assunto','Na placa, o assunto é o horário de funcionamento da biblioteca.','O tema é amplo: do que se está falando. A ideia principal diz algo relevante sobre esse tema.','O cartão menor nomeia o assunto; o outro explica o horário de funcionamento.','Tema','O assunto geral tratado em um texto ou trecho.','Tema é o assunto. Ideia principal é o que o texto diz sobre ele.',['ASSUNTO: biblioteca','IDEIA: abre nos dias úteis','das 9h às 17h']),
  GENERAL_STEP('inferencia','Às vezes, o texto dá pistas sem dizer tudo.','As pistas','Lia entrou carregando um guarda-chuva molhado. Isso mostra que o objeto estava molhado.','Inferir é chegar a uma conclusão apoiada nas pistas. Uma possibilidade inventada, sem apoio suficiente, não é uma conclusão garantida.','O guarda-chuva molhado é a pista. Supor exatamente onde Lia esteve exigiria mais informação.','Inferência','Uma conclusão construída a partir das informações disponíveis e de conhecimentos pertinentes.','A conclusão precisa ser sustentada pelas pistas.',['PISTA: guarda-chuva molhado','CONCLUSÃO: estava molhado','LUGAR: não informado']),
  GENERAL_STEP('conectivo','Uma palavra pode ligar duas ideias.','As ligações','“Lia queria sair, mas estava chovendo.” O mas indica uma oposição entre as ideias.','Conectivos mostram relações como oposição, causa ou conclusão. O sentido exato depende do contexto da frase.','O primeiro cartão traz uma vontade; o segundo apresenta uma situação que contrasta com ela.','Conectivo','Uma palavra ou expressão que relaciona ideias ou partes de um texto.','Leia a relação inteira: o mas pode indicar contraste.',['Lia queria sair','MAS','estava chovendo']),
  GENERAL_STEP('pronome','Uma palavra pode retomar outra.','Quem é quem','“Lia pegou o caderno. Ela anotou a encomenda.” Aqui, ela retoma Lia.','Pronomes e outras expressões podem apontar para elementos mencionados antes. Identificar a referência ajuda a acompanhar o sentido.','O cartão liga “ela” a “Lia”, a pessoa citada antes.','Referência','A relação entre uma expressão e o elemento ao qual ela se refere no contexto.','Siga a pista e veja a quem a palavra se refere.',['Lia pegou o caderno.','Ela anotou a encomenda.','ELA → LIA'])
 ]},
 {id:'port_pontuacao',name:'Pontuação',label:'Português desde o começo',color:'#ad6f34',light:'#fff0d8',symbol:'plan',hero:'A pontuação organiza as ideias.',description:'Veja como frases, pausas e uma vírgula ajudam a organizar a leitura.',root:['Pontuação','organizar a frase'],steps:[
  GENERAL_STEP('frase','Uma frase tem uma intenção.','A frase','“A loja abriu.” É uma frase que informa algo.','A pontuação contribui para organizar a escrita. Para entendê-la, observe a estrutura e o sentido, além da pausa na leitura.','O ponto aparece ao final de uma frase declarativa.','Ponto final','Um sinal usado, entre outros empregos, para encerrar uma frase declarativa.','A pontuação se relaciona à estrutura e ao sentido.',['A loja abriu.','Uma informação completa','termina com ponto.']),
  GENERAL_STEP('lista','A vírgula pode separar itens de uma lista.','Uma lista','“A loja vende pães, bolos e sucos.” A vírgula separa itens da enumeração.','Na lista, os nomes dos produtos aparecem em sequência. Há outras regras e usos para a vírgula.','O primeiro e o segundo item são separados por vírgula; o “e” liga os dois últimos.','Enumeração','Uma sequência de elementos apresentados em uma mesma estrutura.','A vírgula pode organizar uma enumeração.',['pães,','bolos','e sucos']),
  GENERAL_STEP('vocativo','Uma vírgula pode destacar a pessoa chamada.','O chamado','“Lia, guarde o caderno.” O nome mostra com quem alguém está falando.','Vocativo é a expressão usada para chamar ou interpelar alguém. Na escrita, ele costuma ser separado por vírgula.','O nome Lia aparece isolado antes do pedido.','Vocativo','Uma expressão que chama a pessoa ou o interlocutor a quem se dirige a fala.','Ao chamar alguém, observe a vírgula que destaca o chamado.',['Lia,','guarde o caderno.','A fala é dirigida a Lia.']),
  GENERAL_STEP('sujeito','Não separe sujeito e verbo por hábito.','Quem faz','“Os clientes chegaram.” O grupo “os clientes” é o sujeito da ação de chegar.','Na ordem direta, não se coloca vírgula apenas para separar o sujeito de seu verbo. Um trecho intercalado pode exigir outras vírgulas.','O sujeito e o verbo permanecem ligados na frase simples.','Sujeito','O termo da oração com o qual o verbo concorda, conforme a estrutura da frase.','Encontre a ligação entre sujeito e verbo antes de pontuar.',['Os clientes','chegaram.','sujeito → verbo']),
  GENERAL_STEP('aspas','Aspas podem marcar uma fala citada.','A fala','Lia escreveu: “A loja abre às nove”. As aspas destacam as palavras citadas.','As aspas podem ter diferentes funções, como destacar uma citação ou um uso especial de uma palavra. É preciso observar o contexto.','A fala citada aparece entre dois sinais de aspas.','Citação direta','A reprodução das palavras atribuídas a outra fonte, indicada conforme as regras do texto.','Aspas têm usos diferentes; confira a função no trecho.',['Lia disse:','“A loja abre às nove.”','As palavras aparecem citadas.'])
 ]},
 {id:'port_concordancia',name:'Concordância',label:'Português desde o começo',color:'#8c629f',light:'#f1e8f5',symbol:'plan',hero:'As palavras fazem combinações.',description:'Acompanhe como o verbo e os nomes se ajustam aos termos com que se relacionam.',root:['Concordância','observar as relações'],steps:[
  GENERAL_STEP('singular','Uma pessoa e uma ação.','Um cliente','“O cliente chegou.” O verbo chegou acompanha um cliente.','Em uma oração simples, procure quem pratica ou recebe a ação e observe a forma do verbo.','Um cliente está ligado à forma verbal no singular.','Singular','Uma forma que, neste exemplo, se refere a um elemento.','Observe quem está ligado ao verbo.',['O cliente','chegou.','um → chegou']),
  GENERAL_STEP('plural','Mais de um cliente muda a forma.','Vários clientes','“Os clientes chegaram.” Agora o verbo acompanha clientes no plural.','A concordância verbal relaciona o verbo ao sujeito, de acordo com as regras do português. A frase é um exemplo básico.','O plural aparece nos dois lados: clientes e chegaram.','Concordância verbal','A relação de concordância do verbo com o sujeito, conforme a estrutura da oração.','Clientes chegaram; cliente chegou.',['Os clientes','chegaram.','vários → chegaram']),
  GENERAL_STEP('nominal','Nomes também podem concordar.','Os nomes','“Duas encomendas prontas.” As palavras acompanham o nome encomendas.','Na concordância nominal, palavras como artigos, adjetivos e numerais podem se ajustar ao nome com que se relacionam.','Duas, encomendas e prontas aparecem no feminino plural neste exemplo.','Concordância nominal','A relação de concordância entre o nome e termos ligados a ele, conforme as regras da língua.','Veja quais palavras descrevem ou acompanham o nome.',['duas','encomendas','prontas']),
  GENERAL_STEP('distancia','O sujeito pode estar longe do verbo.','A ligação','“Os clientes da loja chegaram.” A expressão “da loja” fica entre o sujeito principal e o verbo.','Para conferir a concordância, identifique o núcleo do sujeito e o verbo. Nem sempre a palavra mais próxima do verbo controla a concordância.','O núcleo clientes está ligado a chegaram, apesar das palavras entre eles.','Núcleo do sujeito','A palavra central do sujeito, em torno da qual os outros elementos se organizam.','Procure o núcleo do sujeito, não apenas a palavra mais próxima.',['Os clientes da loja','chegaram.','clientes → chegaram']),
  GENERAL_STEP('revisar','Leia a frase inteira antes de decidir.','O contexto','A forma do verbo depende da estrutura da oração, não de uma palavra isolada.','Há casos particulares, inclusive com sujeitos compostos e expressões partitivas. Esta história apresenta a ideia inicial para avançar com exemplos específicos.','O cartão lembra os dois passos: localizar o sujeito e observar o verbo.','Revisão da frase','A conferência das relações entre os termos dentro do contexto completo.','Primeiro identifique a estrutura; depois aplique a regra.',['1 · encontre o sujeito','2 · encontre o verbo','3 · confira a relação'])
 ]},
 {id:'mat_frac',name:'Frações',label:'Matemática desde o começo',color:'#537da5',light:'#e9f1fb',symbol:'chart',hero:'Uma parte de cada vez.',description:'Dividir uma figura em partes iguais ajuda a entender frações e a juntar quantidades.',root:['Frações','partes de um todo'],steps:[
  GENERAL_STEP('inteiro','O inteiro é o todo que vamos dividir.','O inteiro','Uma bandeja inteira tem oito pedaços iguais. Vamos olhar para as partes dessa mesma bandeja.','Uma fração representa uma relação entre partes e um todo, ou também pode representar divisão. É preciso saber qual é o inteiro considerado.','Os oito quadradinhos representam oito partes iguais de uma bandeja.','Inteiro','O todo usado como referência para contar as partes.','Para comparar partes, saiba primeiro qual é o todo.',['8 partes iguais','uma bandeja inteira','8/8 = 1 inteiro']),
  GENERAL_STEP('umquarto','Um quarto corresponde a duas partes de oito.','Um quarto','Se dividimos a mesma bandeja em quatro partes iguais, uma delas corresponde a dois dos oito pedaços.','As frações 1/4 e 2/8 são equivalentes porque representam a mesma parte do mesmo inteiro.','Dois dos oito quadradinhos ficam destacados: eles representam 1/4 da bandeja.','Frações equivalentes','Frações diferentes que representam o mesmo valor, como 1/4 e 2/8.','Um quarto do mesmo inteiro é igual a dois oitavos.',['1/4 = 2/8','2 pedaços de 8','mesmo inteiro']),
  GENERAL_STEP('somar','Para somar, use partes do mesmo tamanho.','Somar partes','Lia separou 1/4 pela manhã e 3/8 à tarde. Trocamos 1/4 por 2/8 para juntar.','Com denominadores iguais, somamos os numeradores: 2/8 + 3/8 = 5/8. As parcelas se referem ao mesmo inteiro e não se sobrepõem.','Duas partes e mais três partes somam cinco das oito partes iguais.','Denominador','O número abaixo da barra, que indica em quantas partes iguais o inteiro foi dividido nesta representação.','Partes do mesmo tamanho podem ser somadas diretamente.',['1/4 + 3/8','2/8 + 3/8','= 5/8']),
  GENERAL_STEP('encontrar','A parte conhecida pode revelar o todo.','Encontrar o todo','Cinco oitavos da bandeja representam 30 unidades. Divido 30 em cinco grupos iguais.','Se 5/8 corresponde a 30, então cada oitavo vale 30 ÷ 5 = 6. O inteiro contém oito oitavos: 8 × 6 = 48.','Cinco grupos de 6 formam 30; oito grupos de 6 formam o total.','Parte e todo','Uma relação entre a quantidade conhecida e a unidade completa usada como referência.','Ache o valor de uma parte; depois forme o inteiro.',['5 partes = 30','1 parte = 6','8 partes = 48']),
  GENERAL_STEP('leitura','A barra também pode indicar divisão.','A divisão','Três quartos também pode ser lido como três dividido por quatro.','A fração 3/4 pode ser interpretada como 3 ÷ 4, que é 0,75. O significado no problema depende da grandeza e do contexto.','O mesmo valor é mostrado como fração e como número decimal.','Fração e divisão','A fração a/b, com b diferente de zero, representa a divisão de a por b.','A fração é uma maneira de representar uma divisão.',['3/4 = 3 ÷ 4','= 0,75','mesmo valor'])
 ]},
 {id:'mat_media',name:'Média',label:'Matemática desde o começo',color:'#6e8260',light:'#eaf2df',symbol:'chart',hero:'Compartilhar igualmente ajuda a entender a média.',description:'Vamos juntar os valores e dividi-los igualmente para encontrar uma média simples.',root:['Média','somar e dividir'],steps:[
  GENERAL_STEP('valores','Começamos com uma lista de números.','A lista','Em quatro dias, a loja vendeu 2, 4, 6 e 8 bolos.','A média aritmética simples resume os valores pela soma dividida pela quantidade de valores. Ela não mostra, sozinha, todos os detalhes da lista.','O cartão reúne as quatro quantidades.','Valores','Os números observados no exemplo: 2, 4, 6 e 8.','Antes de calcular, identifique quantos valores existem.',['2 · 4 · 6 · 8','quatro dias','quatro valores']),
  GENERAL_STEP('soma','Primeiro reunimos todas as quantidades.','Somar','Somando os quatro dias, temos 2 + 4 + 6 + 8 = 20 bolos.','A soma reúne as quantidades antes de dividi-las pelo número de observações.','O cartão reúne os quatro números e mostra o total: 20.','Soma','O resultado de adicionar os valores.','Média simples começa pela soma.',['2 + 4 + 6 + 8','= 20 bolos','total dos quatro dias']),
  GENERAL_STEP('divisao','Depois, dividimos pelo número de valores.','Dividir','Foram quatro dias: divido os 20 bolos por 4.','A média é 20 ÷ 4 = 5 bolos por dia. Esse é o valor que cada dia teria se o total fosse distribuído igualmente.','O total 20 é repartido em quatro grupos de 5.','Média aritmética','A soma dos valores dividida pela quantidade de valores.','Some tudo e divida pela quantidade de valores.',['20 ÷ 4 = 5','média: 5 bolos','por dia']),
  GENERAL_STEP('significado','A média não é necessariamente um dos valores.','Interpretar','A média dos dias foi 5, mesmo sem nenhum dia com exatamente 5 bolos vendidos.','Uma média resume a distribuição, mas não diz que todos os valores foram iguais. É útil conferir o conjunto completo.','Os valores originais são 2, 4, 6 e 8; 5 é o resumo calculado.','Interpretação','A explicação do que o resultado significa nas unidades e no contexto do problema.','Média 5 não quer dizer que todos os valores são 5.',['Valores: 2, 4, 6, 8','Média: 5','Os dias são diferentes.']),
  GENERAL_STEP('variacao','O contexto ajuda a usar o número.','O contexto','Saber só a média não mostra qual foi o dia de maior venda.','Ao ler tabelas e gráficos, observe as unidades, o período e as diferenças entre os valores, além do resumo.','A média e os quatro números são apresentados juntos para preservar o contexto.','Distribuição','Como os valores se espalham em um conjunto de dados.','A média é um resumo; volte aos dados para ver detalhes.',['Média: 5','Menor valor: 2','Maior valor: 8'])
 ]},
 {id:'mat_porcento',name:'Porcentagem',label:'Matemática desde o começo',color:'#ad7141',light:'#fff0de',symbol:'chart',hero:'Porcentagem é uma parte de cem.',description:'Use uma figura dividida em cem partes para enxergar descontos e proporções.',root:['Porcentagem','partes em cem'],steps:[
  GENERAL_STEP('cem','Imagine cem partes iguais.','O inteiro','Uma tabela tem 100 quadradinhos. Cada quadradinho é uma parte de cem.','A expressão por cento significa “por cem”. Um por cento equivale a 1/100 do inteiro.','Um conjunto inteiro de 100 partes representa 100%.','Porcentagem','Uma razão cujo denominador é 100. O símbolo % significa por cento.','100% representa o inteiro considerado.',['100 quadradinhos','100 partes em 100','100% do inteiro']),
  GENERAL_STEP('vintecinco','Vinte e cinco por cento é um quarto.','Um quarto','Se pintamos 25 de 100 partes, pintamos 25%.','A fração 25/100 é equivalente a 1/4. Em decimal, corresponde a 0,25.','A figura destaca um bloco de 25 partes entre as 100.','25%','Vinte e cinco em cada cem partes iguais: 25/100 = 1/4 = 0,25.','25% é a quarta parte do inteiro.',['25 de 100','25/100 = 1/4','25% = 0,25']),
  GENERAL_STEP('calculo','Encontre uma parte da quantidade.','Calcular','Um desconto de 25% em R$ 80 corresponde a um quarto de 80: R$ 20.','Calcule 80 × 0,25 = 20. O resultado de uma porcentagem depende do valor que foi escolhido como base.','O preço inicial de R$ 80 gera um desconto de R$ 20.','Base de cálculo','A quantidade à qual aplicamos a porcentagem. Neste caso, o preço inicial.','Primeiro descubra de qual valor a porcentagem é calculada.',['Preço: R$ 80','25% de 80 = R$ 20','valor do desconto']),
  GENERAL_STEP('desconto','O desconto não é o preço final.','O preço final','O produto custava R$ 80. Com desconto de R$ 20, passa a custar R$ 60.','Depois de encontrar o desconto, subtraia-o do preço inicial: 80 − 20 = 60.','O cartão mostra preço, desconto e preço final como três quantidades diferentes.','Desconto','Uma redução aplicada a um valor inicial conforme as condições do problema.','Desconto: R$ 20. Preço depois do desconto: R$ 60.',['R$ 80 − R$ 20','= R$ 60','preço depois do desconto']),
  GENERAL_STEP('comparar','A base muda o resultado.','Comparar','Vinte por cento de 50 é 10. Vinte por cento de 100 é 20.','A mesma taxa aplicada a bases diferentes produz valores diferentes. Em aumentos sucessivos, a base do cálculo também pode mudar.','Os dois cálculos usam 20%, mas partem de valores iniciais diferentes.','Taxa percentual','O percentual usado para comparar ou calcular uma parte da base.','Taxa igual com base diferente pode dar resultado diferente.',['20% de 50 = 10','20% de 100 = 20','bases diferentes'])
 ]},
 {id:'const_fundamentos',name:'Constituição',label:'Direito desde o começo',color:'#6474a2',light:'#ebedf9',symbol:'plan',hero:'As regras principais da nossa organização.',description:'Comece pela ideia de Constituição, direitos e funções dos Poderes, com linguagem simples.',root:['Constituição','direitos e organização'],steps:[
  GENERAL_STEP('regras','Uma sociedade precisa de regras comuns.','Regras comuns','Um grupo combina regras para organizar a vida em comum. Um país também possui normas e instituições.','A Constituição é a norma fundamental do Estado brasileiro. Ela organiza poderes, estabelece princípios e protege direitos.','O cartão reúne o nome do país, a Constituição e a ideia de regras e direitos.','Constituição','A norma fundamental que organiza o Estado e estabelece princípios e direitos.','A Constituição organiza o Estado e protege direitos.' ,['BRASIL','Constituição de 1988','regras e direitos']),
  GENERAL_STEP('direitos','Direitos protegem as pessoas.','Direitos','A Constituição reúne direitos e garantias fundamentais, como a igualdade prevista em seu texto.','Os direitos têm formulações, limites e garantias definidos no ordenamento. Esta cena apresenta a ideia geral; cada artigo deve ser lido com atenção.','O cartão apresenta pessoas e direitos ligados à Constituição.','Direitos fundamentais','Direitos e garantias previstos na Constituição, especialmente em seu Título II.','Consulte a Constituição para conhecer o conteúdo e as condições de cada direito.',['Pessoas','direitos e garantias','Constituição']),
  GENERAL_STEP('poderes','As funções do Estado são distribuídas.','Os Poderes','No Brasil, Legislativo, Executivo e Judiciário são Poderes da União independentes e harmônicos entre si.','Em termos introdutórios, legislar, administrar e julgar são funções associadas a esses Poderes. Cada Poder também exerce outras funções previstas na Constituição.','O cartão apresenta os três Poderes, que possuem relações de controle e cooperação.','Separação de Poderes','Uma organização constitucional que distribui funções e estabelece relações entre os Poderes.','As funções principais ajudam a começar; a Constituição detalha as competências.',['Legislativo · Executivo','Judiciário','independentes e harmônicos']),
  GENERAL_STEP('municipio','O município faz parte da organização do país.','O município','Parnamirim é um município do Rio Grande do Norte.','A organização político-administrativa da República Federativa do Brasil compreende União, estados, Distrito Federal e municípios, todos autônomos nos termos da Constituição.','A figura liga o município ao estado e ao país sem apagar a autonomia prevista.','Município','Um ente da organização político-administrativa brasileira, com autonomia nos termos constitucionais.','Os entes têm competências e autonomia definidas na Constituição.',['Brasil','Rio Grande do Norte','Parnamirim']),
  GENERAL_STEP('lei','Leia a norma e suas condições.','A leitura da lei','Uma frase curta pode resumir uma ideia, mas uma regra jurídica pode conter condições e exceções.','Em questões de direito, confira a legislação indicada no edital e sua versão aplicável. Termos absolutos podem ser verdadeiros ou falsos dependendo da norma.','O texto da lei vem acompanhado de um marcador para lembrar que o contexto precisa ser conferido.','Texto legal','A redação normativa que deve ser estudada conforme o edital, as alterações e o contexto.','Uma palavra como “sempre” merece conferência; ela não é gabarito automático.',['Leia o artigo','observe as condições','verifique as exceções'])
 ]}
);

JOURNEYS.push(
 {id:'port_crase',name:'Crase',label:'Português desde o começo',color:'#ac637c',light:'#fae7ed',symbol:'plan',hero:'Duas letras podem se encontrar.',description:'Entenda primeiro o encontro entre a preposição e o artigo antes de olhar para o acento.',root:['Crase','o encontro de dois as'],steps:[
  GENERAL_STEP('ligacao','Algumas palavras pedem uma ligação.','A ligação','Na frase “Vou a um lugar”, a palavra a liga o verbo ao destino.','Alguns verbos e nomes se relacionam com outros termos por meio de uma preposição. Cada construção deve ser analisada no contexto.','O cartão apresenta a palavra que liga a ação ao destino.','Preposição','Uma palavra que estabelece relação entre termos, como a, de, em e para.','Veja se a palavra anterior pede a preposição a.',['Vou a um lugar','vou → a → lugar','a é a ligação']),
  GENERAL_STEP('artigo','Alguns nomes admitem um artigo.','O artigo','Dizemos “a biblioteca”. Neste exemplo, a palavra a acompanha o nome feminino.','Artigos definidos podem acompanhar substantivos: a biblioteca, o mercado. Seu uso varia conforme a construção e o contexto.','O cartão aproxima o artigo a do nome biblioteca.','Artigo definido','Uma palavra que acompanha um substantivo, como o, a, os ou as.','Veja se o nome aceita o artigo a.',['a biblioteca','a = artigo','biblioteca = nome']),
  GENERAL_STEP('encontro','A preposição e o artigo podem se juntar.','O encontro','Em “Vou à biblioteca”, o verbo pede a preposição a, e biblioteca admite o artigo a.','Nesse exemplo, a preposição a e o artigo a se fundem. O acento grave indica essa fusão na escrita.','O cartão representa as duas letras se tornando uma só, com acento.','Crase','A fusão de duas vogais iguais; no uso comum, de preposição a com artigo a ou as.','Neste exemplo: a + a = à.',['vou a + a biblioteca','a + a = à','vou à biblioteca']),
  GENERAL_STEP('masculino','Uma troca pode ajudar a observar o artigo.','Comparar','Dizemos “Vou ao mercado”. Ao comparar com “Vou à biblioteca”, vemos a preposição e o artigo no exemplo masculino.','A troca por um termo masculino pode ajudar em construções semelhantes: ao indica a + o. Ela não resolve todos os casos de crase.','O cartão compara duas frases com a mesma relação de destino.','Comparação','Um recurso para observar uma estrutura semelhante sem substituir a análise da frase.','O teste do ao ajuda em alguns casos, mas não é regra universal.',['vou ao mercado','vou à biblioteca','compare as estruturas']),
  GENERAL_STEP('semartigo','Sem artigo feminino, o acento pode não aparecer.','Sem encontro','Em “Vou a pé”, a expressão não recebe artigo feminino. Não ocorre a fusão do exemplo anterior.','O emprego do acento grave depende da construção. Há outros casos, como locuções femininas e pronomes demonstrativos, que exigem estudo específico.','O cartão mostra que nem todo a leva acento grave.','Acento grave','O sinal gráfico em à e às usado para indicar determinadas ocorrências de crase.','Não coloque acento em todo a: examine a construção.',['vou a pé','sem artigo feminino','sem acento neste exemplo'])
 ]},
 {id:'logic_proposicoes',name:'Lógica e proposições',label:'Raciocínio desde o começo',color:'#7384b7',light:'#e9edfa',symbol:'chart',hero:'Uma frase pode ser verdadeira ou falsa.',description:'Comece pela ideia de afirmação, negação e ligação entre duas afirmações.',root:['Lógica','afirmações e relações'],steps:[
  GENERAL_STEP('afirmacao','Uma afirmação pode ter valor de verdade.','A afirmação','“A loja está aberta” é uma frase que afirma algo. Em uma situação definida, ela pode ser verdadeira ou falsa.','Na lógica proposicional, uma proposição é uma afirmação à qual se atribui um valor de verdade. Uma pergunta, por exemplo, não faz uma afirmação.','O cartão apresenta a frase e os dois valores possíveis.','Proposição','Uma afirmação que, na lógica clássica, recebe valor verdadeiro ou falso.','Uma proposição afirma algo que pode ser avaliado.',['A loja está aberta.','valor possível: verdadeiro','ou falso']),
  GENERAL_STEP('negacao','Negar inverte a afirmação.','A negação','Se a frase é “A loja está aberta”, sua negação é “A loja não está aberta”.','Na lógica clássica, a negação de uma proposição verdadeira é falsa, e a negação de uma proposição falsa é verdadeira.','O cartão coloca a frase e sua negação lado a lado.','Negação','Uma operação lógica que inverte o valor de verdade de uma proposição.','Negar não significa simplesmente trocar uma palavra qualquer.',['Está aberta.','NÃO está aberta.','um valor inverte o outro']),
  GENERAL_STEP('e','O E reúne duas condições.','A palavra E','“A loja está aberta e Lia está presente” só é verdadeira quando as duas afirmações são verdadeiras.','A conjunção lógica é verdadeira quando ambas as proposições que a compõem são verdadeiras.','O cartão apresenta duas afirmações ligadas por E.','Conjunção','A operação lógica E, verdadeira somente quando as duas partes são verdadeiras.','Para o E ser verdadeiro, as duas partes precisam ser verdadeiras.',['Loja aberta','E','Lia presente']),
  GENERAL_STEP('ou','O OU lógico inclui a possibilidade das duas.','A palavra OU','“A loja abre de manhã ou à tarde” é verdadeira se ao menos uma das duas afirmações for verdadeira.','Na disjunção inclusiva usual da lógica, a afirmação também é verdadeira quando as duas partes são verdadeiras. O uso cotidiano de ou pode ser diferente.','O cartão registra que uma parte ou as duas podem ser verdadeiras.','Disjunção','A operação lógica OU, geralmente inclusiva, verdadeira quando ao menos uma parte é verdadeira.','No OU inclusivo, as duas partes também podem ser verdadeiras.',['manhã OU tarde','uma das duas','ou as duas']),
  GENERAL_STEP('condicional','SE e ENTÃO ligam duas proposições.','Se... então','Considere “Se chove, então a rua está molhada”. É uma afirmação sobre a relação entre duas situações.','Na lógica clássica, uma condicional é falsa quando a primeira parte é verdadeira e a segunda é falsa. Nos demais casos, é verdadeira.','O cartão destaca o caso que torna a condicional falsa.','Condicional','Uma proposição composta no formato se P, então Q.','A condicional é falsa quando P é verdadeiro e Q é falso.',['SE chove,','ENTÃO rua molhada','falsa: chove e rua seca'])
 ]},
 {id:'mat_probabilidade',name:'Probabilidade',label:'Matemática desde o começo',color:'#aa8351',light:'#f8ecd8',symbol:'chart',hero:'Contar possibilidades ajuda a pensar.',description:'Um saquinho com bolinhas ajuda a entender chances sem prometer resultados.',root:['Probabilidade','comparar possibilidades'],steps:[
  GENERAL_STEP('sorteio','Imagine um sorteio simples.','O sorteio','Em um saquinho há quatro bolinhas iguais: uma azul e três amarelas. Vamos retirar uma sem olhar.','A probabilidade descreve um modelo de incerteza. Para este exemplo, supomos que as quatro bolinhas tenham a mesma chance de sair.','O cartão apresenta a composição do saquinho.','Experimento aleatório','Uma situação cujo resultado específico não é conhecido antes de ocorrer.','Primeiro veja o que pode acontecer e quais hipóteses foram feitas.',['1 bolinha azul','3 bolinhas amarelas','4 bolinhas no total']),
  GENERAL_STEP('possiveis','Conte todos os resultados possíveis.','As possibilidades','Há quatro bolinhas, então há quatro possibilidades individuais igualmente prováveis neste exemplo.','Ao contar resultados, defina com clareza o que distingue cada possibilidade e se elas têm chances iguais.','O cartão registra quatro bolinhas possíveis.','Espaço amostral','O conjunto de resultados possíveis definidos para o experimento.','Conte os resultados possíveis antes de calcular.',['azul · amarela 1','amarela 2 · amarela 3','4 possibilidades']),
  GENERAL_STEP('favoravel','Conte os resultados que interessam.','O que interessa','Se queremos retirar a azul, há uma possibilidade favorável entre as quatro.','Quando os resultados são igualmente prováveis, a probabilidade é a quantidade de resultados favoráveis dividida pelo total.','O cartão compara uma possibilidade favorável com quatro possíveis.','Evento','O resultado ou conjunto de resultados de interesse no experimento.','A chance depende dos resultados favoráveis e do total possível.',['favorável: 1 azul','possíveis: 4','1 ÷ 4 = 1/4']),
  GENERAL_STEP('percentual','Uma fração pode virar porcentagem.','A chance','Um quarto é o mesmo que 25 em 100: a chance no modelo é 25%.','A fração 1/4 equivale a 0,25 e a 25%. Isso não significa que cada sequência de quatro sorteios terá necessariamente uma azul.','O cartão mostra três formas de representar o mesmo valor.','Probabilidade','Uma medida de possibilidade entre zero e um no modelo considerado.','25% descreve a chance do modelo, não uma promessa de resultado.',['1/4 = 0,25','= 25%','não é uma garantia']),
  GENERAL_STEP('condicoes','A chance muda se as condições mudarem.','Novas condições','Se uma bolinha amarela for retirada e não voltar, restam uma azul e duas amarelas.','Supondo chances iguais entre as três restantes, a chance da azul no próximo sorteio será 1/3. A condição sobre qual bolinha saiu importa.','O cartão registra o novo conjunto depois de retirar uma amarela.','Probabilidade condicional','A probabilidade calculada levando em conta uma informação ou condição conhecida.','Confira o que mudou antes de repetir a conta.',['1 azul + 2 amarelas','3 restantes','azul: 1/3'])
 ]}
);

// Fundamentos de informática presentes em provas locais e editais atuais.
JOURNEYS.push(
 {id:'info_hardware',name:'Partes do computador',label:'Informática desde o começo',color:'#4a8c80',light:'#e1f1ed',symbol:'cloud',hero:'Um computador tem peças com papéis diferentes.',description:'Vamos separar equipamento, programas, memória e armazenamento.',root:['Computador','peças e programas'],steps:[
  GENERAL_STEP('equipamento','Algumas partes podem ser tocadas.','Peças físicas','Tela, teclado e computador são exemplos de partes físicas que usamos para acessar informações.','Hardware é o conjunto de componentes físicos de um sistema computacional. Eles trabalham com programas, também chamados de software.','O cartão apresenta exemplos de peças e a palavra usada para esse conjunto.','Hardware','Os componentes físicos, como processador, memória, tela e teclado.','Hardware são componentes físicos; software reúne programas.',['Hardware','teclado · tela · memória','partes físicas']),
  GENERAL_STEP('entrada','Alguns dispositivos recebem informações.','Entrada','Quando você digita no teclado, envia letras para o computador.','Dispositivos de entrada permitem que dados sejam enviados ao sistema. Teclado, mouse e microfone são exemplos.','O cartão mostra exemplos de dispositivos que capturam ou enviam dados.','Entrada','O envio ou a captura de dados para processamento pelo sistema.','Teclado e mouse são exemplos de entrada.',['Teclado → computador','Mouse → computador','dados entram']),
  GENERAL_STEP('saida','Outros dispositivos apresentam resultados.','Saída','Depois de digitar, as letras aparecem na tela. Uma impressora pode colocá-las no papel.','Dispositivos de saída mostram, reproduzem ou registram resultados. A mesma peça pode combinar funções de entrada e saída.','O cartão mostra dois exemplos de apresentação dos resultados.','Saída','A apresentação ou transferência de resultados a partir do sistema.','Tela e impressora são exemplos de saída.',['computador → tela','computador → impressora','resultados saem']),
  GENERAL_STEP('ram','A memória de trabalho ajuda durante o uso.','Memória RAM','Ao abrir um programa, o sistema usa memória para manter dados de trabalho enquanto ele está em execução.','A memória RAM é usada pelo sistema para acesso rápido a dados em uso. Seu conteúdo normalmente se perde quando a alimentação é desligada.','O cartão aproxima memória RAM da ideia de trabalho em andamento.','Memória RAM','Memória de acesso rápido, geralmente volátil, utilizada para dados e programas em execução.','RAM é memória de trabalho; ela não substitui o armazenamento.',['RAM','dados em uso','geralmente volátil']),
  GENERAL_STEP('armazenar','Arquivos também precisam ser guardados.','Armazenar','Um documento salvo pode permanecer no SSD ou em outro meio depois que o computador é desligado.','Armazenamento guarda dados em meios como SSDs, discos e unidades externas. Fazer cópias de segurança reduz o risco de perder o único arquivo.','O cartão diferencia a memória de trabalho do local onde o arquivo foi salvo.','Armazenamento','Um meio de guardar dados de forma persistente, como um SSD.','Salvar e manter cópias são coisas diferentes de apenas abrir um arquivo.',['RAM: dados em uso','SSD: arquivo salvo','backup: uma cópia'])
 ]},
 {id:'info_arquivos',name:'Arquivos e pastas',label:'Informática desde o começo',color:'#997243',light:'#f9eedb',symbol:'plan',hero:'Um nome ajuda a encontrar cada arquivo.',description:'Conheça pastas, extensões, cópias e cuidados antes de abrir um arquivo.',root:['Arquivos','organizar e guardar'],steps:[
  GENERAL_STEP('arquivo','Um arquivo guarda informações.','O arquivo','Uma carta digitada pode ser salva em um arquivo com um nome, por exemplo relatorio.docx.','Um arquivo é uma unidade de dados armazenados. Há arquivos de texto, imagem, áudio e muitos outros formatos.','O cartão apresenta um nome fictício e destaca que ele identifica um arquivo.','Arquivo','Uma unidade de dados armazenada e identificada por um nome.','Um arquivo pode guardar texto, imagem ou outro tipo de informação.',['relatorio.docx','um nome de arquivo','contém dados']),
  GENERAL_STEP('pasta','Uma pasta ajuda a organizar.','A pasta','Você pode guardar relatórios de um concurso em uma pasta chamada Estudos.','Pastas organizam arquivos e outras pastas. O caminho indica onde um arquivo está localizado.','O cartão representa uma pasta contendo um documento.','Pasta','Uma forma de organizar arquivos e subpastas em um sistema de arquivos.','Uma pasta pode conter arquivos e outras pastas.',['Estudos/','  relatorio.docx','pasta → arquivo']),
  GENERAL_STEP('extensao','A parte final sugere um formato.','Extensão','Em relatorio.docx, a extensão é .docx. Ela costuma indicar o formato ou ajudar o sistema a escolher um aplicativo.','Extensões como .pdf, .jpg e .docx ajudam a identificar formatos, mas o nome sozinho não garante que o conteúdo seja seguro ou válido.','O cartão destaca exemplos de extensões.','Extensão','Parte final do nome de um arquivo que pode indicar seu formato ou associação com programas.','A extensão dá uma pista, mas não garante segurança.',['relatorio.docx','foto.jpg · edital.pdf','o final sugere o formato']),
  GENERAL_STEP('copiar','Copiar e mover não são a mesma coisa.','Copiar ou mover','Ao copiar um documento para outra pasta, uma nova cópia passa a existir. Ao mover, ele muda de localização.','As operações podem variar conforme o dispositivo e o sistema. Depois de copiar, confira se a cópia está acessível e íntegra.','O cartão compara as duas ações de organização.','Cópia','Uma reprodução de dados que pode ser guardada em outro local.','Copiar cria outra cópia; mover muda o local do item.',['copiar → outra cópia','mover → outro local','confira o resultado']),
  GENERAL_STEP('backup','Uma cópia de segurança precisa ser utilizável.','Cópias de segurança','Um arquivo importante pode ter uma cópia em outro dispositivo ou serviço apropriado.','Backup é uma cópia para recuperação. Uma cópia no mesmo dispositivo pode ser perdida junto com o original; convém testar a restauração.','O cartão lembra original, cópia separada e teste de recuperação.','Backup','Uma cópia de dados mantida para ajudar na recuperação após perda ou falha.','Uma boa cópia é guardada com cuidado e pode ser recuperada.',['original','cópia separada','teste de recuperação'])
 ]},
 {id:'info_planilhas',name:'Planilhas e fórmulas',label:'Informática desde o começo',color:'#547f77',light:'#e5f1e9',symbol:'chart',hero:'Uma planilha organiza números em células.',description:'Aprenda o endereço de uma célula e veja como fórmulas simples funcionam.',root:['Planilhas','células e fórmulas'],steps:[
  GENERAL_STEP('celula','Uma tabela tem linhas e colunas.','Células','Imagine uma tabela: a primeira coluna é A e a segunda linha é 2. O encontro delas é a célula A2.','Em uma planilha, cada célula é identificada pela coluna e pela linha. Ela pode guardar texto, número ou fórmula.','O cartão mostra a coluna, a linha e o endereço da célula.','Célula','O espaço na interseção de uma linha e uma coluna de uma planilha.','Coluna A com linha 2 forma o endereço A2.',['coluna A','linha 2','célula A2']),
  GENERAL_STEP('formula','Uma fórmula faz um cálculo.','Fórmula','Se A1 vale 2 e A2 vale 4, a fórmula =A1+A2 calcula 6.','Em planilhas como o Excel, uma fórmula começa com sinal de igual. Ela pode usar números, operadores e referências a células.','O cartão mostra duas células e o resultado de uma soma.','Fórmula','Uma expressão usada pela planilha para calcular um resultado.','O sinal = inicia a fórmula neste exemplo.',['A1 = 2 · A2 = 4','=A1+A2','= 6']),
  GENERAL_STEP('intervalo','Um intervalo reúne células.','Intervalo','A1:A3 representa as células de A1 até A3 na mesma coluna.','O sinal de dois-pontos indica um intervalo contínuo de células. Uma função pode calcular usando os valores do intervalo.','O cartão lista as três células do intervalo.','Intervalo','Um conjunto de células identificado por suas referências, como A1:A3.','A1:A3 vai de A1 até A3.',['A1 · A2 · A3','A1:A3','três células']),
  GENERAL_STEP('media','MÉDIA resume os números.','Média','Se A1, A2 e A3 contêm 2, 4 e 6, =MÉDIA(A1:A3) resulta em 4.','A função MÉDIA calcula a média aritmética dos números informados. No Excel, células vazias no intervalo são ignoradas; zeros são incluídos.','O cartão reúne os valores, a fórmula e o resultado.','Função MÉDIA','Uma função que calcula a média aritmética dos valores numéricos considerados.','Célula vazia e célula com zero podem ter efeitos diferentes.',['2 · 4 · 6','=MÉDIA(A1:A3)','resultado: 4']),
  GENERAL_STEP('se','SE escolhe um resultado conforme uma condição.','Condição','Se A1 contém 8, a fórmula =SE(A1>=7;"Aprovado";"Revisar") retorna Aprovado.','A função SE verifica uma condição e retorna um valor se ela for verdadeira e outro se for falsa. Os separadores podem depender da configuração do programa.','O cartão apresenta a condição e os dois resultados possíveis.','Função SE','Uma função que avalia uma condição e escolhe entre dois resultados.','SE organiza uma condição e seus dois resultados possíveis.',['A1 >= 7?','sim → Aprovado','não → Revisar'])
 ]},
 {id:'info_documentos',name:'Documentos e Word',label:'Informática desde o começo',color:'#687dad',light:'#e9effa',symbol:'plan',hero:'Um documento fica mais fácil de navegar quando tem estrutura.',description:'Veja a diferença entre aparência e estrutura, e como criar um sumário automático.',root:['Documentos','títulos e sumário'],steps:[
  GENERAL_STEP('texto','Um documento reúne informações.','Documento','Um relatório pode ter um título, parágrafos e seções.','Um editor de texto ajuda a criar, alterar e formatar documentos. O conteúdo e a organização precisam ser pensados juntos.','O cartão mostra as partes comuns de um relatório.','Editor de texto','Um programa para escrever, revisar e organizar documentos.','Um relatório reúne conteúdo em uma estrutura.',['Título','parágrafos','seções']),
  GENERAL_STEP('formatacao','A aparência pode destacar uma palavra.','Aparência','Colocar uma palavra em negrito muda a forma como ela aparece na página.','Formatação inclui fonte, tamanho, negrito e alinhamento. A combinação de teclas depende do programa, idioma e configuração.','O cartão mostra uma palavra com a indicação de negrito.','Formatação','A definição da aparência de elementos do documento.','A aparência ajuda a leitura; atalhos dependem da configuração.',['texto normal','texto em negrito','aparência diferente']),
  GENERAL_STEP('estilos','Um estilo pode identificar um título.','Títulos','Ao marcar “Introdução” como Título 1 no Word, você indica seu papel na estrutura.','Estilos de título organizam níveis do documento e ajudam recursos de navegação e sumário. Apenas aumentar o tamanho da fonte pode não criar essa estrutura.','O cartão diferencia marcar a função de título de apenas mudar a aparência.','Estilo de título','Uma formatação com significado estrutural, como Título 1 ou Título 2.','Identificar títulos facilita navegação e sumário.',['Introdução','estilo: Título 1','estrutura do documento']),
  GENERAL_STEP('sumario','O sumário pode reunir os títulos.','Sumário','No Word, um sumário automático pode usar os títulos marcados no documento.','A documentação do Word orienta usar estilos de título e inserir o sumário pela guia Referências. Nomes e interface podem variar entre versões.','O cartão liga os títulos ao sumário que será criado.','Sumário automático','Uma lista gerada a partir da estrutura de títulos do documento.','Primeiro marque os títulos; depois insira o sumário.',['Título 1','Referências → Sumário','lista de seções']),
  GENERAL_STEP('atualizar','Depois de editar, confira o sumário.','Atualizar','Se um título ou número de página mudar, atualize o sumário para refletir as alterações.','Um sumário automático pode ser atualizado no Word; um sumário manual não é preenchido automaticamente pelos estilos. Confira o resultado antes de entregar.','O cartão lembra os passos de editar, atualizar e conferir.','Atualização','A ação de recalcular o conteúdo gerado para refletir mudanças no documento.','Depois de alterar o documento, atualize e revise o sumário.',['editar documento','atualizar sumário','conferir resultado'])
 ]}
);

// Novas histórias introduzem os símbolos antes dos mapas e dos exercícios.
JOURNEYS.push(
 {id:'mat_razao',name:'Razão e proporção',label:'Matemática desde o começo',color:'#ac713f',light:'#fff0de',symbol:'chart',hero:'Uma receita pode crescer mantendo a mesma proporção.',description:'Descubra uma unidade antes de aumentar uma receita, sem precisar decorar setas.',root:['Proporção','comparar e ajustar'],steps:[
  GENERAL_STEP('receita','Primeiro, veja a receita conhecida.','A receita','Duas porções usam quatro colheres de farinha.','Vamos supor que todas as porções sejam iguais e que a receita mantenha a mesma quantidade de farinha por porção.','O cartão apresenta as duas quantidades que conhecemos.','Grandeza','Uma quantidade que pode ser medida ou contada, como porções e colheres.','Identifique o que está sendo contado.',['2 porções','4 colheres','mesma receita']),
  GENERAL_STEP('unidade','Descubra a quantidade para uma porção.','Uma porção','Se duas porções usam quatro colheres, uma porção usa duas colheres.','Dividir quatro colheres por duas porções dá duas colheres por porção, nas condições da receita.','O cartão mostra a divisão e a unidade do resultado.','Razão','Uma comparação por divisão entre duas quantidades, desde que o divisor não seja zero.','Divida 4 colheres por 2 porções.',['4 ÷ 2 = 2','2 colheres','por porção']),
  GENERAL_STEP('crescer','Agora faça três porções.','Três porções','Cada porção usa duas colheres. Três porções usam seis colheres.','Multiplicamos três porções por duas colheres por porção: 3 × 2 = 6 colheres.','O cartão relaciona uma porção com três porções.','Proporcionalidade direta','Uma relação em que uma grandeza é obtida multiplicando a outra por uma constante.','Três grupos de duas colheres somam seis.',['1 porção → 2 colheres','3 porções → 6 colheres','3 × 2 = 6']),
  GENERAL_STEP('inversa','Algumas situações funcionam de outro jeito.','Trabalho fixo','Se duas máquinas iguais terminam um lote em seis horas, quatro máquinas podem terminar em três horas nas condições ideais do exemplo.','Para o mesmo trabalho, com máquinas igualmente produtivas e sem paradas, dobrar as máquinas reduz o tempo pela metade.','O cartão mostra duas situações para o mesmo lote.','Proporcionalidade inversa','Uma relação em que o produto das duas grandezas permanece constante.','Compare sempre a situação e as condições.',['2 máquinas → 6 horas','4 máquinas → 3 horas','mesmo lote']),
  GENERAL_STEP('verificar','A conta precisa combinar com a situação.','Conferir','Ao dobrar as porções, esperamos dobrar a farinha se a receita for mantida.','Nem toda relação é proporcional. Taxas fixas, desperdício, limites e outras condições podem mudar o cálculo.','O cartão lembra de ler o problema, conferir as condições e escrever a unidade.','Conferência','A comparação do resultado com as condições e grandezas do problema.','Confira condições, direção e unidade.',['leia as condições','faça a conta','confira a unidade'])
 ]},
 {id:'mat_equacoes',name:'Equação do primeiro grau',label:'Matemática desde o começo',color:'#596ead',light:'#e9effa',symbol:'plan',hero:'Uma igualdade funciona como uma balança.',description:'Vamos descobrir um número desconhecido fazendo a mesma operação dos dois lados.',root:['Equação','descobrir um valor'],steps:[
  GENERAL_STEP('igualdade','O sinal de igual mostra uma igualdade.','Os dois lados','A frase 3 + 2 = 5 diz que os dois lados têm o mesmo valor.','Uma igualdade compara duas expressões que representam o mesmo valor.','O cartão mostra a soma à esquerda e o resultado à direita.','Igualdade','Uma afirmação de que duas expressões têm o mesmo valor.','Os dois lados devem representar o mesmo valor.',['3 + 2 = 5','lado esquerdo = 5','lado direito = 5']),
  GENERAL_STEP('incognita','Uma letra pode representar o valor que procuramos.','O desconhecido','Em x + 3 = 7, x é o número que, somado a três, resulta em sete.','A letra x representa a incógnita. Resolver é encontrar o valor que torna a igualdade verdadeira.','O cartão apresenta a letra, a soma e o resultado.','Incógnita','Uma letra ou símbolo que representa um valor desconhecido em uma equação.','x é o valor que queremos descobrir.',['x + 3 = 7','x é desconhecido','a soma vale 7']),
  GENERAL_STEP('equilibrio','Faça a mesma operação nos dois lados.','Manter igual','Para retirar o três do lado esquerdo, subtraímos três dos dois lados.','De x + 3 = 7 passamos a x + 3 − 3 = 7 − 3. A igualdade permanece equilibrada.','O cartão mostra menos três nos dois lados.','Princípio aditivo','Somar ou subtrair a mesma quantidade dos dois lados preserva a igualdade.','Faça a mesma operação nos dois lados.',['x + 3 = 7','x + 3 − 3 = 7 − 3','x = 4']),
  GENERAL_STEP('dividir','Às vezes, precisamos dividir.','Isolar x','Se 2x = 8, dividimos os dois lados por dois.','Como 2 é diferente de zero, 2x ÷ 2 = 8 ÷ 2 resulta em x = 4.','O cartão registra a igualdade inicial, a divisão e o valor obtido.','Princípio multiplicativo','Multiplicar ou dividir os dois lados pelo mesmo número não nulo preserva a igualdade.','Não divida por zero.',['2x = 8','2x ÷ 2 = 8 ÷ 2','x = 4']),
  GENERAL_STEP('prova','Volte à frase para conferir.','Verificar','Substituindo x por quatro em x + 3 = 7, obtemos 4 + 3 = 7.','A substituição confirma se o valor encontrado satisfaz a equação do exemplo.','O cartão mostra a equação e a substituição.','Solução','Um valor que torna verdadeira a equação.','Substitua o valor na equação original.',['x + 3 = 7','4 + 3 = 7','4 é solução'])
 ]},
 {id:'logic_conjuntos',name:'Conjuntos',label:'Raciocínio lógico desde o começo',color:'#5a8c70',light:'#e5f3e9',symbol:'blocks',hero:'Podemos juntar grupos e observar o que eles têm em comum.',description:'Veja união e interseção com pessoas que gostam de diferentes atividades.',root:['Conjuntos','grupos e elementos'],steps:[
  GENERAL_STEP('grupos','Um conjunto é uma coleção de elementos.','O grupo','O grupo A contém Ana e Bia. O grupo B contém Bia e Caio.','Os elementos são os membros do conjunto. Usamos chaves para mostrar os membros em uma lista.','O cartão apresenta os grupos A e B.','Conjunto','Uma coleção de elementos considerados em uma situação.','Observe quem pertence a cada grupo.',['A = {Ana, Bia}','B = {Bia, Caio}','Bia está nos dois']),
  GENERAL_STEP('intersecao','A interseção reúne quem está nos dois grupos.','Em comum','Bia aparece em A e também em B. Portanto, a interseção contém Bia.','A interseção A ∩ B contém os elementos que pertencem simultaneamente aos dois conjuntos.','O cartão destaca Bia como elemento comum.','Interseção','O conjunto dos elementos que pertencem a ambos os conjuntos.','Interseção pede o que está em comum.',['A ∩ B = {Bia}','Bia pertence a A','e também pertence a B']),
  GENERAL_STEP('uniao','A união reúne os elementos dos dois grupos.','Juntar','Ana, Bia e Caio aparecem em pelo menos um dos grupos.','A união A ∪ B contém todos os elementos de A ou de B. Cada pessoa é listada uma vez no conjunto.','O cartão mostra Ana, Bia e Caio sem repetir Bia.','União','O conjunto dos elementos que pertencem a pelo menos um dos conjuntos.','Ao juntar os grupos, não repita elementos.',['A ∪ B = {Ana, Bia, Caio}','Bia aparece uma vez','total: 3 pessoas']),
  GENERAL_STEP('contagem','A parte comum não deve ser contada duas vezes.','Contar','Há duas pessoas em A e duas em B, mas Bia está nos dois grupos.','Para contar a união, somamos 2 + 2 e retiramos uma contagem repetida: 2 + 2 − 1 = 3.','O cartão apresenta a soma, o elemento repetido e o total.','Contagem da união','Para dois conjuntos finitos, soma-se o tamanho de cada conjunto e subtrai-se o tamanho da interseção.','Subtraia uma vez o grupo contado duas vezes.',['2 em A + 2 em B','− 1 pessoa em comum','= 3 pessoas']),
  GENERAL_STEP('diferenca','Também podemos separar quem está só em um grupo.','Diferença','Ana está em A, mas não está em B.','A diferença A − B contém elementos de A que não pertencem a B. A ordem importa: B − A contém Caio.','O cartão compara A menos B com B menos A.','Diferença','Os elementos do primeiro conjunto que não pertencem ao segundo.','A − B e B − A podem ser diferentes.',['A − B = {Ana}','B − A = {Caio}','a ordem importa'])
 ]}
);

JOURNEYS.push(
 {id:'port_acentos',name:'Acentuação',label:'Português desde o começo',color:'#ad6685',light:'#f9eaf1',symbol:'plan',hero:'Algumas sílabas soam mais fortes; algumas recebem acento.',description:'Conheça a sílaba tônica antes de observar alguns sinais escritos.',root:['Acentuação','som e escrita'],steps:[
  GENERAL_STEP('silabas','As palavras podem ser divididas em sílabas.','As sílabas','A palavra café pode ser dividida em duas sílabas: ca-fé.','Sílabas são unidades da fala que, na escrita, ajudam a analisar a organização da palavra.','O cartão divide a palavra café em duas partes.','Sílaba','Uma unidade sonora de uma palavra.','Primeiro, observe as sílabas da palavra.',['café','ca · fé','duas sílabas']),
  GENERAL_STEP('tonica','Uma sílaba pode ser pronunciada com mais força.','A sílaba forte','Em café, a última sílaba, fé, é pronunciada com mais destaque.','A sílaba tônica é a sílaba pronunciada com maior intensidade. Sua posição ajuda a classificar a palavra.','O cartão destaca a última sílaba de café.','Sílaba tônica','A sílaba pronunciada com maior destaque em uma palavra.','Tônica é a sílaba mais forte na pronúncia.',['ca · FÉ','última sílaba','café']),
  GENERAL_STEP('oxitona','Quando a última sílaba é tônica, a palavra é oxítona.','Última sílaba','Em café, fé é a última sílaba e é a tônica.','Café é uma oxítona terminada em e e recebe acento gráfico. Nem toda oxítona é acentuada.','O cartão compara café com papel, outra oxítona que não leva acento.','Oxítona','Palavra cuja sílaba tônica é a última.','Oxítona indica posição da sílaba tônica.',['ca · FÉ → café','pa · PEL → papel','ambas são oxítonas']),
  GENERAL_STEP('paroxitona','A sílaba forte pode ser a penúltima.','Penúltima sílaba','Em livro, a sílaba li é tônica. Em fácil, a sílaba fá é tônica.','Livro e fácil são paroxítonas. A posição tônica, por si só, não determina que todas tenham acento gráfico.','O cartão apresenta uma paroxítona sem acento e outra com acento.','Paroxítona','Palavra cuja sílaba tônica é a penúltima.','Paroxítonas seguem regras de acentuação.',['LI · vro → livro','FÁ · cil → fácil','penúltima sílaba']),
  GENERAL_STEP('proparoxitona','A sílaba forte também pode ser a antepenúltima.','Antepenúltima sílaba','Em música, a sílaba mú é a antepenúltima e é tônica.','Proparoxítonas recebem acento gráfico. Há outras regras para hiatos, ditongos e casos específicos.','O cartão destaca mú e apresenta a palavra escrita.','Proparoxítona','Palavra cuja sílaba tônica é a antepenúltima.','Proparoxítonas são acentuadas.',['MÚ · si · ca','antepenúltima sílaba','música'])
 ]},
 {id:'port_sujeito',name:'Sujeito e predicado',label:'Português desde o começo',color:'#5a8c70',light:'#e5f3e9',symbol:'plan',hero:'Uma frase pode contar algo sobre alguém.',description:'Descubra como o sujeito se relaciona com o verbo e o restante da oração.',root:['A oração','termos e relações'],steps:[
  GENERAL_STEP('frase','Uma frase pode transmitir uma informação.','A frase','Na biblioteca, Lia organizou os livros.','A frase comunica uma informação. Oração é uma estrutura que tem verbo ou locução verbal.','O cartão mostra a frase e destaca o verbo organizou.','Oração','Uma estrutura organizada em torno de um verbo ou de uma locução verbal.','Procure o verbo na oração.',['Lia organizou os livros.','verbo: organizou','uma oração']),
  GENERAL_STEP('verbo','O verbo mostra a ação neste exemplo.','A ação','Na frase, organizou mostra o que aconteceu.','Os verbos também podem indicar estado ou fenômeno; o significado depende do contexto.','O cartão separa a forma verbal do restante da frase.','Verbo','Uma classe de palavras que pode indicar ações, estados ou fenômenos e apresenta flexões.','Localize a forma verbal no contexto.',['Lia organizou os livros.','organizou → verbo','aconteceu no passado']),
  GENERAL_STEP('sujeito','O sujeito se relaciona com o verbo.','Quem organiza','Em “Lia organizou os livros”, Lia é o sujeito.','Nesta oração, Lia é quem realizou a ação. A identificação do sujeito depende da estrutura; nem sempre ele pratica uma ação.','O cartão liga Lia ao verbo organizou.','Sujeito','O termo com o qual o verbo concorda, quando há sujeito na oração.','Lia se relaciona ao verbo organizou.',['Lia → sujeito','organizou → verbo','Lia organizou']),
  GENERAL_STEP('predicado','O predicado apresenta o que se diz do sujeito.','O que se diz','Na frase “Lia organizou os livros”, o predicado é “organizou os livros”.','O predicado é organizado em torno do verbo e contém aquilo que se declara sobre o sujeito nessa análise.','O cartão separa Lia do trecho organizou os livros.','Predicado','O termo da oração que contém o verbo e, quando há sujeito, apresenta o que se diz dele.','Sujeito: Lia. Predicado: organizou os livros.',['Lia','organizou os livros','sujeito + predicado']),
  GENERAL_STEP('variacao','Nem toda oração tem sujeito expresso.','Outras estruturas','Em “Choveu ontem”, o verbo indica fenômeno da natureza e a oração não tem sujeito.','Existem sujeitos expressos, ocultos, indeterminados e orações sem sujeito. Esta história inicia o assunto com dois exemplos.','O cartão compara uma oração com sujeito e outra sem sujeito.','Oração sem sujeito','Uma oração construída com verbo impessoal, como chover indicando fenômeno da natureza.','Não invente um sujeito onde ele não existe.',['Lia chegou → sujeito: Lia','Choveu → sem sujeito','observe o verbo'])
 ]},
 {id:'port_verbos',name:'Verbos e tempos',label:'Português desde o começo',color:'#4e6eb5',light:'#e9effa',symbol:'cycle',hero:'Um verbo ajuda a situar o que acontece.',description:'Compare ações no passado, no presente e no futuro em exemplos simples.',root:['Verbos','tempo e sentido'],steps:[
  GENERAL_STEP('acao','Uma palavra pode indicar uma ação.','A ação','Lia estuda para a prova. A palavra estuda indica a ação nesse exemplo.','Um verbo pode indicar ação, estado ou fenômeno, dependendo do contexto.','O cartão destaca a forma estuda.','Verbo','Uma classe de palavras que varia, entre outras formas, em tempo, modo, pessoa e número.','Comece procurando o verbo na frase.',['Lia estuda.','estuda → verbo','uma ação']),
  GENERAL_STEP('presente','O presente situa o fato no momento ou em um hábito.','Hoje','Lia estuda todos os dias. A forma estuda pode indicar um hábito no presente.','O valor temporal depende da frase; o presente também pode ter outros usos.','O cartão associa estuda à rotina descrita.','Presente','Um tempo verbal que pode situar fatos no momento atual ou expressar hábitos.','Leia o contexto para interpretar o tempo.',['Lia estuda','todos os dias','presente: hábito']),
  GENERAL_STEP('passado','Uma forma verbal pode apresentar um fato passado.','Ontem','Lia estudou ontem. A forma estudou apresenta uma ação concluída no passado nesse exemplo.','O pretérito pode ter formas e sentidos diferentes, como estudou e estudava.','O cartão mostra estudou junto com a palavra ontem.','Pretérito','Uma forma verbal associada, em muitos contextos, a fatos anteriores ao momento da fala.','Ontem, Lia estudou.',['ontem','Lia estudou','fato passado']),
  GENERAL_STEP('futuro','O futuro pode apresentar um fato posterior.','Amanhã','Lia estudará amanhã. A forma estudará indica uma ação futura no contexto.','O futuro também tem usos e formas diferentes, que precisam ser lidos no contexto.','O cartão mostra estudará com a palavra amanhã.','Futuro','Uma forma verbal que pode indicar um fato posterior ao momento da fala.','Amanhã, Lia estudará.',['amanhã','Lia estudará','fato futuro']),
  GENERAL_STEP('modo','O modo ajuda a expressar a atitude em relação ao fato.','Possibilidade','“Se Lia estudar, entenderá o assunto.” A forma estudar aparece em uma condição.','O modo verbal participa da construção de sentidos, como afirmação, possibilidade ou pedido. O significado depende da frase.','O cartão destaca a condição e sua consequência.','Modo verbal','Uma categoria das formas verbais, como indicativo, subjuntivo e imperativo.','Observe o verbo junto com a frase.',['se Lia estudar','ela entenderá','condição → consequência'])
 ]}
);

JOURNEYS.push(
 {id:'adm_redacao',name:'Comunicação oficial',label:'Administração desde o começo',color:'#5d78a7',light:'#e9effa',symbol:'plan',hero:'Um documento ajuda uma instituição a comunicar uma decisão.',description:'Acompanhe uma mensagem oficial simples e entenda quem escreve, para quem e por quê.',root:['Comunicação oficial','clareza e propósito'],steps:[
  GENERAL_STEP('situacao','Uma instituição precisa comunicar uma informação.','A necessidade','Uma unidade precisa informar a outra o horário de uma reunião.','Antes de escrever, é útil identificar o assunto, o destinatário e a finalidade da comunicação.','O cartão apresenta a necessidade de enviar uma informação.','Finalidade','O objetivo da comunicação: informar, solicitar, responder ou encaminhar algo.','Saiba o que precisa comunicar.',['assunto: reunião','destinatário: outra unidade','objetivo: informar']),
  GENERAL_STEP('destinatario','A mensagem precisa chegar à pessoa certa.','Para quem','A unidade prepara o documento para o setor responsável pela reunião.','Identificar o destinatário e o canal correto ajuda a encaminhar a mensagem. Cada órgão pode ter procedimentos próprios.','O cartão identifica quem envia e quem recebe.','Destinatário','A pessoa, unidade ou instituição a quem a comunicação se dirige.','Confira quem deve receber.',['remetente: unidade A','destinatário: unidade B','assunto: reunião']),
  GENERAL_STEP('clareza','Escrever de forma clara ajuda a pessoa a entender.','O texto','“A reunião será em 3 de novembro, às 14h, na sala 2.”','O exemplo usa informações específicas. Uma mensagem oficial deve buscar clareza, precisão, objetividade e outras qualidades exigidas pelo órgão.','O cartão separa a data, o horário e o local.','Clareza','A qualidade de uma mensagem compreensível para quem precisa utilizá-la.','Informe o necessário com palavras claras.',['data: 3 de novembro','hora: 14h','local: sala 2']),
  GENERAL_STEP('partes','Um documento oficial pode ter partes identificáveis.','O ofício','No padrão federal de ofício, é comum identificar o documento, o destinatário, o assunto e o texto.','O Manual da Presidência apresenta um padrão para comunicações do Executivo federal. Outros órgãos podem adotar normas próprias.','O cartão lista partes gerais de um documento.','Ofício','Uma forma de comunicação oficial utilizada conforme as normas aplicáveis.','Confira o padrão do órgão e o destinatário.',['identificação','destinatário e assunto','texto e assinatura']),
  GENERAL_STEP('conferir','Antes de enviar, confira a mensagem.','Revisão','A equipe verifica a data, o destinatário e a informação que será enviada.','A revisão inclui conteúdo, clareza, procedimentos, identificação e proteção de dados quando necessários.','O cartão registra uma pequena lista de conferência.','Revisão','A conferência do documento antes de seu encaminhamento.','Confira o conteúdo e o canal antes de enviar.',['destinatário correto','informação clara','revisar antes de enviar'])
 ]},
 {id:'adm_atendimento',name:'Atendimento ao público',label:'Administração desde o começo',color:'#5a8c70',light:'#e5f3e9',symbol:'heart',hero:'Atender é ouvir, orientar e encaminhar com respeito.',description:'Veja uma pessoa buscando um serviço e acompanhe como a equipe pode ajudá-la.',root:['Atendimento','ouvir e orientar'],steps:[
  GENERAL_STEP('acolher','A pessoa chega com uma necessidade.','Receber','Uma pessoa procura informações sobre como solicitar um serviço.','O atendimento começa com acolhimento respeitoso e atenção às necessidades da pessoa.','O cartão apresenta a pessoa e o motivo do atendimento.','Usuário','A pessoa que utiliza ou busca um serviço.','Receba a pessoa com respeito.',['pessoa procura um serviço','acolher com respeito','ouvir a necessidade']),
  GENERAL_STEP('ouvir','Escutar ajuda a entender o pedido.','Escutar','A pessoa explica que precisa saber quais documentos são necessários.','Escuta atenta ajuda a identificar a demanda sem presumir a resposta antes de entendê-la.','O cartão mostra a necessidade de documentação.','Demanda','A necessidade ou solicitação apresentada pela pessoa.','Ouça antes de orientar.',['pedido: solicitar serviço','dúvida: documentos','identificar a demanda']),
  GENERAL_STEP('orientar','Uma orientação precisa ser compreensível.','Orientar','A equipe explica o procedimento com linguagem simples e verifica se a informação está atualizada.','O atendimento deve informar de maneira clara sobre os passos e os canais disponíveis.','O cartão mostra a sequência de orientações.','Orientação','Uma explicação para ajudar a pessoa a compreender os próximos passos.','Explique de forma clara e precisa.',['passo 1: documentos','passo 2: canal correto','informação atualizada']),
  GENERAL_STEP('acessibilidade','Pessoas diferentes podem precisar de apoios diferentes.','Acesso','O atendimento procura oferecer condições acessíveis conforme as necessidades e as regras aplicáveis.','Respeito, cortesia e acessibilidade contribuem para um atendimento adequado.','O cartão apresenta formas de contato sem expor dados pessoais.','Acessibilidade','Condições para que pessoas com diferentes necessidades possam acessar serviços e informações.','Adapte a comunicação com respeito.',['atendimento respeitoso','informação acessível','sem discriminação']),
  GENERAL_STEP('encaminhar','Quando necessário, encaminhe para o setor competente.','Próximo passo','Se outra unidade é responsável, a pessoa recebe uma orientação sobre como procurar essa unidade.','Encaminhar corretamente e proteger dados pessoais fazem parte de um atendimento responsável.','O cartão mostra orientação e encaminhamento.','Encaminhamento','O direcionamento de uma demanda para o canal ou setor responsável.','Oriente sem prometer o que você não pode cumprir.',['confira o setor','informe o próximo passo','proteja dados pessoais'])
 ]},
 {id:'adm_patrimonio',name:'Patrimônio e contabilidade',label:'Contabilidade desde o começo',color:'#ad7d44',light:'#fff0de',symbol:'chart',hero:'Uma organização precisa conhecer o que possui e o que deve.',description:'Um exemplo simples apresenta ativo, passivo e patrimônio líquido.',root:['Patrimônio','recursos e obrigações'],steps:[
  GENERAL_STEP('recursos','Uma organização pode ter recursos.','O que possui','Uma pequena organização tem R$ 1.000 em caixa e um equipamento avaliado em R$ 2.000 neste exemplo.','Vamos usar valores fictícios para entender a relação básica. Reconhecimento e mensuração de ativos têm critérios próprios.','O cartão mostra os dois recursos do exemplo.','Ativo','Um recurso controlado pela entidade que atende à definição contábil aplicável.','O exemplo tem R$ 3.000 em recursos.',['caixa: R$ 1.000','equipamento: R$ 2.000','total: R$ 3.000']),
  GENERAL_STEP('obrigacao','A organização também pode ter obrigações.','O que deve','Ela deve R$ 800 a um fornecedor por uma compra anterior.','Um passivo é uma obrigação presente que atende à definição contábil aplicável.','O cartão mostra a obrigação do exemplo.','Passivo','Uma obrigação presente da entidade decorrente de eventos passados, conforme a estrutura contábil aplicável.','A dívida do exemplo é uma obrigação.',['compra anterior','dívida: R$ 800','passivo do exemplo']),
  GENERAL_STEP('liquido','A diferença ajuda a encontrar o patrimônio líquido.','A diferença','Os recursos somam R$ 3.000 e a obrigação é de R$ 800. A diferença é R$ 2.200.','No exemplo simplificado, patrimônio líquido é o valor residual dos ativos após a dedução dos passivos.','O cartão apresenta a subtração.','Patrimônio líquido','O valor residual dos ativos depois de deduzidos os passivos.','Ativo menos passivo: R$ 2.200.',['ativo: R$ 3.000','passivo: R$ 800','patrimônio líquido: R$ 2.200']),
  GENERAL_STEP('equacao','A mesma relação pode ser escrita de outro jeito.','A igualdade','R$ 3.000 em ativos = R$ 800 em passivos + R$ 2.200 de patrimônio líquido.','Essa é uma representação da equação patrimonial. Os valores precisam se referir ao mesmo momento e à mesma entidade.','O cartão mostra os dois lados da igualdade.','Equação patrimonial','A relação ativo = passivo + patrimônio líquido.','Os dois lados representam o mesmo total.',['R$ 3.000 =','R$ 800 + R$ 2.200','ativo = passivo + PL']),
  GENERAL_STEP('contexto','A realidade exige mais detalhes que um exemplo.','Além da conta','A organização deve observar as regras de registro e avaliação aplicáveis à sua situação.','No setor público e no setor privado existem normas e procedimentos próprios. Este exemplo é apenas uma introdução aos nomes e à igualdade.','O cartão lembra que o exemplo precisa ser aprofundado.','Normas contábeis','Regras e orientações que disciplinam o reconhecimento, a mensuração e a divulgação das informações.','Confira as normas e o programa do cargo.',['exemplo simplificado','consulte as normas','aprofunde pelo edital'])
 ]}
);

JOURNEYS.push(
 {id:'adm_reunioes',name:'Organizar reuniões',label:'Administração desde o começo',color:'#5d78a7',light:'#e9effa',symbol:'plan',hero:'Uma reunião fica mais clara quando sabemos por que vamos nos encontrar.',description:'Acompanhe a preparação, os assuntos e o registro de uma reunião simples.',root:['Reuniões','preparar e registrar'],steps:[
  GENERAL_STEP('objetivo','Primeiro, definimos para que serve a reunião.','O objetivo','Uma equipe precisa combinar os horários de atendimento do mês seguinte.','Antes de convocar pessoas, defina o objetivo e confirme se a reunião é necessária.','O cartão apresenta o resultado desejado.','Objetivo','O resultado que se pretende alcançar com a reunião.','Saiba o que o grupo precisa decidir ou discutir.',['tema: horários de atendimento','objetivo: combinar a escala','uma decisão necessária']),
  GENERAL_STEP('pauta','Depois, organizamos os assuntos.','A pauta','A equipe lista os horários atuais e a proposta para o mês seguinte.','Pauta é a lista de assuntos que orienta a conversa. Dependendo da reunião, pode incluir duração e responsáveis.','O cartão apresenta dois itens para a conversa.','Pauta','A relação de assuntos previstos para uma reunião.','Pauta apresenta o que será tratado.',['1 · horários atuais','2 · proposta de escala','assuntos da reunião']),
  GENERAL_STEP('convite','As pessoas precisam saber quando e onde participar.','A convocação','A equipe informa o horário, o local e a pauta aos participantes.','Convite ou convocação deve seguir o procedimento e a antecedência exigidos pela instituição, quando existirem.','O cartão mostra os dados que ajudam a chegar à reunião.','Convocação','A comunicação pela qual participantes são chamados para uma reunião.','Confira data, horário, local e pauta.',['dia e horário','local ou link','pauta e participantes']),
  GENERAL_STEP('registro','Durante a reunião, registramos o que for necessário.','A ata','Ao final da conversa, a equipe registra a decisão sobre os horários e quem fará cada encaminhamento.','Uma ata pode registrar presenças, assuntos, deliberações e encaminhamentos, conforme as regras do órgão.','O cartão mostra decisão, responsável e prazo.','Ata','Um registro escrito do que ocorreu e foi deliberado na reunião, conforme as regras aplicáveis.','Pauta é o plano; ata é o registro.',['decisão: nova escala','responsável: equipe','prazo: data combinada']),
  GENERAL_STEP('acompanhar','Depois, acompanhe o que foi combinado.','O acompanhamento','A equipe encaminha o registro e confere se a escala foi divulgada.','Os passos posteriores dependem das decisões e do procedimento institucional.','O cartão lembra de registrar, encaminhar e acompanhar.','Encaminhamento','Uma providência definida a partir de uma discussão ou decisão.','Registre os próximos passos.',['registrar a decisão','encaminhar às pessoas','acompanhar a tarefa'])
 ]},
 {id:'adm_eventos',name:'Planejar eventos',label:'Administração desde o começo',color:'#ac713f',light:'#fff0de',symbol:'board',hero:'Um evento precisa de pessoas, lugar, tempo e organização.',description:'Veja como preparar um encontro acessível, da ideia à conferência final.',root:['Eventos','planejar e acompanhar'],steps:[
  GENERAL_STEP('finalidade','Comece pelo motivo do encontro.','O objetivo','Uma equipe vai organizar uma oficina de atendimento para trinta pessoas.','Defina objetivo, público e formato. Esses dados orientam as demais escolhas.','O cartão mostra o evento e o público previsto.','Público','As pessoas a quem o evento se destina.','Defina objetivo e público.',['oficina de atendimento','30 participantes previstos','objetivo: compartilhar orientações']),
  GENERAL_STEP('local','O local precisa atender às necessidades.','Espaço e acesso','A equipe procura uma sala com capacidade suficiente e acesso adequado.','Considere localização, infraestrutura e acessibilidade física e comunicacional desde o planejamento.','O cartão lista espaço, acesso e equipamentos.','Acessibilidade','Condições para participação de pessoas com diferentes necessidades.','Acessibilidade faz parte do planejamento.',['sala adequada','acesso e comunicação','equipamentos necessários']),
  GENERAL_STEP('tarefas','As tarefas precisam de responsáveis e prazos.','O cronograma','Uma pessoa confirma a sala; outra verifica os equipamentos antes da oficina.','Um cronograma ou lista de verificação ajuda a acompanhar tarefas, prazos e responsáveis.','O cartão relaciona tarefas a responsáveis.','Cronograma','Uma organização de atividades e prazos ao longo do tempo.','Cada tarefa deve ter um responsável e um prazo.',['reservar sala → responsável','testar equipamento → responsável','conferir prazos']),
  GENERAL_STEP('custos','Os recursos e despesas precisam ser previstos.','O orçamento','A equipe verifica os recursos necessários e as autorizações antes de contratar ou gastar.','Passagens, hospedagem e reembolsos seguem regras, autorizações e comprovações aplicáveis.','O cartão diferencia previsão, autorização e comprovante.','Orçamento','Uma previsão organizada de recursos e despesas para uma finalidade.','Previsão não é autorização automática.',['prever recursos','verificar autorização','guardar comprovantes']),
  GENERAL_STEP('avaliacao','No fim, confira o que aconteceu.','A avaliação','Depois da oficina, a equipe verifica presença, resultados e pontos para melhorar.','A prestação de contas e a avaliação seguem as normas do órgão e as responsabilidades definidas.','O cartão mostra conferir resultados e registrar melhorias.','Avaliação','A análise do que foi realizado e do que pode ser melhorado.','Confira resultados e registre aprendizados.',['conferir presença','avaliar resultados','registrar melhorias'])
 ]},
 {id:'adm_latim',name:'Expressões latinas',label:'Comunicação desde o começo',color:'#ad6685',light:'#f9eaf1',symbol:'plan',hero:'Algumas expressões vêm do latim e aparecem em documentos.',description:'Entenda alguns exemplos pelo contexto, sem precisar decorar uma lista inteira de uma vez.',root:['Expressões latinas','ler pelo contexto'],steps:[
  GENERAL_STEP('contexto','Uma expressão antiga pode aparecer em um texto atual.','A expressão','O documento informa que uma comissão foi criada ad hoc para uma tarefa específica.','Algumas expressões latinas são mantidas em documentos. O contexto ajuda a compreender o sentido.','O cartão destaca a expressão e sua finalidade.','Expressão latina','Um conjunto de palavras de origem latina usado em determinado contexto.','Leia a expressão dentro da frase.',['comissão ad hoc','para uma tarefa específica','observe o contexto']),
  GENERAL_STEP('adhoc','Ad hoc pode indicar uma finalidade específica.','Para este fim','Uma comissão ad hoc foi formada para analisar um assunto determinado.','A expressão indica, nesse uso, algo destinado àquele fim ou caso específico.','O cartão liga ad hoc à finalidade da comissão.','Ad hoc','Para este fim ou caso específico, conforme o contexto.','Ad hoc: para este fim.',['comissão ad hoc','analisar uma tarefa','para este fim']),
  GENERAL_STEP('inloco','In loco indica o próprio local.','No local','A equipe realizou uma visita in loco ao prédio onde ocorrerá o evento.','A expressão indica uma verificação ou ação no local mencionado.','O cartão liga a visita ao local do evento.','In loco','No próprio local.','In loco: no local.',['visita in loco','ao prédio do evento','verificação no local']),
  GENERAL_STEP('caput','Caput pode nomear a parte inicial de um artigo.','O artigo','Em um artigo de lei, o caput é o enunciado principal antes de parágrafos e incisos.','Na leitura de normas, a expressão é usada para identificar a parte inicial de um artigo.','O cartão mostra o artigo e o trecho inicial.','Caput','O enunciado principal de um artigo, na referência à estrutura de um texto normativo.','Caput: parte inicial do artigo.',['artigo da lei','caput: enunciado principal','parágrafos e incisos']),
  GENERAL_STEP('apud','Apud pode indicar uma citação encontrada em outra fonte.','A fonte','Uma autora menciona uma frase de outra pessoa em um livro que você leu.','Apud pode indicar que uma citação foi conhecida por meio de uma obra intermediária. Confira as normas de referência aplicáveis.','O cartão mostra a autora original e a obra consultada.','Apud','Citado por ou conforme, usado em referências para indicar uma fonte intermediária.','Diferencie o autor original da fonte consultada.',['autora original','obra consultada','apud: citado por'])
 ]},
 {id:'mat_geometria',name:'Geometria e sequências',label:'Matemática desde o começo',color:'#4d7f73',light:'#e4f2ee',symbol:'chart',hero:'Formas, medidas e padrões que crescem passo a passo.',description:'Veja como medir o contorno e a área de um espaço, localizar pontos e acompanhar sequências numéricas.',root:['Geometria e padrões','medir, localizar e acompanhar'],steps:[
  GENERAL_STEP('perimetro','O contorno mostra a volta completa.','O contorno','Um canteiro retangular tem lados de 3 metros e 4 metros. Para cercá-lo, somamos todos os lados.','Perímetro é a medida do contorno de uma figura plana. No retângulo de 3 m por 4 m, somamos 3 + 4 + 3 + 4 = 14 m.','O cartão mostra os quatro lados somados em metros lineares.','Perímetro','A soma das medidas dos lados que formam o contorno de uma figura plana.','Perímetro mede a volta inteira.',['lados: 3 m e 4 m','3 + 4 + 3 + 4','perímetro = 14 m']),
  GENERAL_STEP('area','A superfície preenche o interior.','A superfície','Para cobrir o mesmo canteiro com placas de 1 metro quadrado, multiplicamos 3 por 4.','A área mede a superfície interna. Em um retângulo de 3 m por 4 m, cabem 3 × 4 = 12 quadrados de 1 m².','O cartão diferencia a volta (14 m) do preenchimento interno (12 m²).','Área','A medida de uma superfície, expressa em unidades quadradas como m² ou cm².','Contorno usa unidade linear; área usa unidade quadrada.',['base: 4 m · altura: 3 m','4 × 3 = 12 m²','superfície preenchida']),
  GENERAL_STEP('coordenadas','Dois números localizam um ponto no plano.','As coordenadas','No mapa quadriculado, a torre A está na posição horizontal −3 e vertical 2.','No plano cartesiano, um par ordenado (x, y) indica a abscissa e a ordenada. Dois pontos distintos determinam uma única reta.','O cartão apresenta o ponto A(−3, 2) e o ponto B(5, −4), como no exemplo da prova de Parnamirim.','Plano cartesiano','Um sistema de dois eixos perpendiculares usado para localizar pontos e representar retas e curvas.','O primeiro número é x; o segundo é y.',['ponto A: (−3, 2)','ponto B: (5, −4)','dois pontos → uma reta']),
  GENERAL_STEP('progressoes','Uma sequência pode somar ou multiplicar.','As sequências','Se os postos têm 10, 20 e 40 guardas, cada termo é o dobro do anterior.','Na progressão aritmética (PA), soma-se uma razão constante. Na progressão geométrica (PG), multiplica-se por uma razão constante.','O cartão mostra a multiplicação por 2 a cada passo: 10, 20, 40, 80.','Progressão geométrica','Uma sequência em que cada termo, a partir do segundo, é o anterior multiplicado por uma razão constante.','Somar constante → PA. Multiplicar constante → PG.',['10 · 20 · 40 · 80','multiplica por 2','razão q = 2']),
  GENERAL_STEP('funcoes','Uma função relaciona cada entrada a uma saída.','A relação','Se cada caderno custa R$ 8, o valor para x cadernos pode ser escrito como f(x) = 8x.','Uma função associa cada elemento do domínio a um único valor de saída. No gráfico, podemos visualizar como uma grandeza varia em relação à outra.','O cartão mostra entradas e suas respectivas saídas.','Função','Uma regra que relaciona cada valor do domínio a um único valor no contradomínio.','Para cada entrada do domínio, há um resultado definido.',['1 caderno → R$ 8','2 cadernos → R$ 16','f(x) = 8x'])
 ]},
 {id:'mat_combinatoria',name:'Contagem e matrizes',label:'Matemática desde o começo',color:'#5b6fa8',light:'#e9eef9',symbol:'blocks',hero:'Organizar escolhas, múltiplos e tabelas de números.',description:'Entenda divisibilidade, contagem de possibilidades e a organização de dados em matrizes.',root:['Contagem e matrizes','escolher, dividir e organizar'],steps:[
  GENERAL_STEP('divisibilidade','Múltiplos e divisores ajudam a sincronizar ciclos.','MMC e MDC','Se uma ronda passa a cada 4 horas e outra a cada 6 horas, elas coincidem a cada 12 horas.','O mínimo múltiplo comum (MMC) encontra o menor múltiplo positivo comum. O máximo divisor comum (MDC) encontra o maior divisor compartilhado para repartir sem sobra.','O cartão mostra os múltiplos de 4 e de 6 se encontrando no 12.','MMC e MDC','MMC é o menor múltiplo positivo comum; MDC é o maior divisor inteiro comum.','Encontros futuros usam múltiplos; divisões iguais usam divisores.',['múltiplos de 4: 4, 8, 12...','múltiplos de 6: 6, 12...','MMC(4, 6) = 12']),
  GENERAL_STEP('multiplicativo','Decisões em etapas podem ser multiplicadas.','As etapas','Com 3 camisas e 2 calças diferentes, podemos montar 3 × 2 = 6 combinações de uniforme.','Pelo princípio multiplicativo, se uma escolha tem m opções e a seguinte tem n opções independentes, há m × n pares possíveis.','O cartão liga cada uma das 3 camisas às 2 calças.','Princípio multiplicativo','Se etapas sucessivas têm m e n modos de ocorrer, o total de escolhas conjuntas é m × n.','E entre etapas independentes → multiplique as possibilidades.',['3 camisas','2 calças','3 × 2 = 6 opções']),
  GENERAL_STEP('ordem','Às vezes a ordem muda o resultado; às vezes não.','Ordem importa?','Escolher Ana e Bia para uma comissão de duas pessoas é a mesma dupla que escolher Bia e Ana.','Quando a ordem dos escolhidos cria resultados distintos (como 1º e 2º lugar), falamos em arranjo. Quando importa apenas o grupo formado, falamos em combinação.','O cartão compara fila ordenada com dupla sem hierarquia.','Combinação','Contagem de subconjuntos em que a ordem dos elementos escolhidos não diferencia o grupo.','Antes de calcular, pergunte: trocar a ordem cria outro caso?',['1º Ana, 2º Bia ≠ 1º Bia, 2º Ana','dupla {Ana, Bia} = {Bia, Ana}','confira se a ordem importa']),
  GENERAL_STEP('matriz','Uma matriz organiza números em linhas e colunas.','A matriz','Podemos registrar as vendas de 2 lojas em 3 dias usando uma tabela de 2 linhas por 3 colunas.','Na matemática, uma matriz m × n possui m linhas horizontais e n colunas verticais. Cada posição é identificada por linha e coluna.','O cartão destaca a linha 1 e a coluna 2 da tabela numérica.','Matriz','Uma tabela retangular de elementos dispostos em linhas e colunas.','Na notação linha × coluna, a linha vem primeiro.',['2 linhas · 3 colunas','matriz 2 × 3','elemento na linha i, coluna j']),
  GENERAL_STEP('exponencial','Potências repetem multiplicações; logaritmos fazem a pergunta inversa.','Potência e log','Se 2 elevado a 3 vale 8, o logaritmo de 8 na base 2 responde: qual expoente transforma 2 em 8?','Na potência 2³ = 8, a base 2 é multiplicada três vezes. O logaritmo log₂(8) = 3 procura exatamente esse expoente.','O cartão mostra os dois lados da mesma relação: potência e logaritmo.','Logaritmo','O expoente ao qual se deve elevar a base para obter determinado número positivo.','Logaritmo pergunta qual é o expoente.',['2³ = 2 × 2 × 2 = 8','log₂(8) = 3','o expoente é 3'])
 ]},
 {id:'penal_fundamentos',name:'Direito Penal e Processo',label:'Direito desde o começo',color:'#7c5b8f',light:'#f1eaf6',symbol:'shield',hero:'Limites legais para definir crimes, investigar fatos e proteger garantias.',description:'Compreenda a reserva legal, a legítima defesa, os crimes funcionais, o inquérito e as regras de prisão.',root:['Penal e Processo','lei prévia, investigação e garantias'],steps:[
  GENERAL_STEP('legalidade','Não existe crime sem uma lei anterior que o defina.','A lei anterior','Uma conduta só pode ser punida como crime se uma lei já a definia assim antes do fato acontecer.','O princípio da reserva legal e da anterioridade está na Constituição (art. 5º, XXXIX) e no art. 1º do Código Penal. A lei penal só retroage para beneficiar o réu.','O cartão mostra que a lei precisa existir antes do fato.','Anterioridade penal','Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.','A lei penal não volta ao passado para prejudicar; só para beneficiar.',['1º · lei em vigor','2º · fato praticado','sem lei prévia → não há crime']),
  GENERAL_STEP('ilicitude','A lei prevê situações em que a reação afasta a ilicitude.','Legítima defesa','Quem usa moderadamente os meios necessários para repelir injusta agressão, atual ou iminente, age em legítima defesa.','O Código Penal (arts. 23 a 25) prevê excludentes de ilicitude: estado de necessidade, legítima defesa, estrito cumprimento de dever legal e exercício regular de direito.','O cartão destaca os requisitos da legítima defesa no art. 25 do Código Penal.','Excludente de ilicitude','Hipótese legal em que o fato não constitui crime por estar amparado pelo direito.','Legítima defesa exige agressão injusta, atual ou iminente, e uso moderado dos meios.',['agressão injusta','atual ou iminente','meios necessários com moderação']),
  GENERAL_STEP('crimes','Cada crime tem elementos próprios na lei.','Tipos de crime','Se um servidor público se apropria de bem móvel de que tem a posse em razão do cargo, o Código Penal descreve peculato.','Diferenciar os verbos e elementos da lei evita confusões: furto é subtrair coisa alheia móvel; apropriação indébita ocorre quando o agente já detinha a posse lícita; peculato envolve o cargo público.','O cartão compara a posse em razão do cargo com outras figuras penais.','Peculato','Crime praticado por funcionário público contra a administração em geral, previsto no art. 312 do Código Penal.','Observe o verbo do artigo e se há vínculo com a função pública.',['furto: subtrair','apropriação: já tinha posse','peculato: em razão do cargo']),
  GENERAL_STEP('inquerito','O inquérito policial reúne elementos para esclarecer o fato.','O inquérito','Antes de um processo judicial, a polícia judiciária conduz o inquérito para apurar a infração e sua autoria.','O inquérito policial é um procedimento administrativo informativo. Nos crimes de ação penal pública incondicionada, pode ser iniciado de ofício, por requisição ou requerimento.','O cartão mostra o investigado (indiciado) na fase de inquérito.','Inquérito policial','Procedimento administrativo destinado a apurar infrações penais e fornecer elementos ao titular da ação penal.','No inquérito fala-se em indiciado; no processo penal, após recebimento da peça, em réu/acusado.',['fase preliminar','apurar autoria e materialidade','sujeito investigado: indiciado']),
  GENERAL_STEP('prisao','A prisão exige flagrante delito ou ordem judicial fundamentada.','Regras de prisão','Ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente.','Pelo art. 301 do CPP, qualquer do povo pode prender quem está em flagrante delito (facultativo), enquanto as autoridades policiais e seus agentes têm o dever de fazê-lo.','O cartão diferencia a faculdade do cidadão comum do dever dos agentes policiais.','Prisão em flagrante','Medida restritiva realizada no momento da infração ou logo após, nas hipóteses do art. 302 do CPP.','Cidadão comum: pode prender em flagrante. Autoridade policial e agentes: devem prender.',['flagrante delito','ou ordem judicial escrita','cidadão pode · agente deve'])
 ]},
 {id:'legis_especial',name:'Legislação especial e guardas',label:'Direito desde o começo',color:'#4b7c68',light:'#e4f2eb',symbol:'shield',hero:'Leis específicas protegem pessoas, bens públicos e a convivência nas cidades.',description:'Conheça o Estatuto Geral das Guardas Municipais e as principais leis especiais cobradas em concursos.',root:['Legislação especial','proteção preventiva e direitos'],steps:[
  GENERAL_STEP('guardas','A guarda municipal atua na proteção preventiva do município.','Estatuto das Guardas','Pela Lei 13.022/2014, incumbe às guardas municipais a proteção de bens, serviços, logradouros públicos municipais e instalações do Município.','Seus princípios mínimos incluem proteção dos direitos humanos fundamentais, preservação da vida, patrulhamento preventivo, compromisso com a evolução social e uso progressivo da força.','O cartão reúne o caráter preventivo e a proteção do patrimônio e serviços municipais.','Lei 13.022/2014','O Estatuto Geral das Guardas Municipais, que disciplina princípios, competências e exigências das corporações.','Diante de flagrante delito, a guarda encaminha o autor ao delegado, preservando o local do crime.',['patrulhamento preventivo','bens, serviços e instalações','preservar a vida e direitos']),
  GENERAL_STEP('mariadapenha','A Lei Maria da Penha protege a mulher contra violência doméstica e familiar.','Lei 11.340/2006','Configura violência doméstica e familiar contra a mulher qualquer ação ou omissão baseada no gênero que lhe cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial.','A lei abrange o âmbito da unidade doméstica, da família ou qualquer relação íntima de afeto, independentemente de coabitação. A autoridade deve ouvir a ofendida e encaminhar pedido de medidas protetivas.','O cartão destaca os três âmbitos de aplicação da Lei 11.340/2006.','Violência doméstica','Violência baseada no gênero ocorrida na unidade doméstica, na família ou em relação íntima de afeto.','A proteção da Lei 11.340/2006 não exige que agressor e vítima morem juntos no momento do fato.',['unidade doméstica','família ou relação de afeto','medidas protetivas de urgência']),
  GENERAL_STEP('ecaidoso','Crianças, adolescentes e pessoas idosas têm proteção prioritária.','ECA e Estatuto do Idoso','Pelo ECA (Lei 8.069/1990), menores de 18 anos são penalmente inimputáveis e sujeitos a medidas específicas. Pelo Estatuto da Pessoa Idosa (Lei 10.741/2003), nenhum idoso será objeto de negligência ou violência.','Considera-se criança a pessoa até 12 anos incompletos e adolescente aquela entre 12 e 18 anos. A pessoa idosa é aquela com idade igual ou superior a 60 anos.','O cartão mostra as faixas etárias legais e o dever de proteção integral.','Inimputabilidade etária','Previsão constitucional e legal de que menores de 18 anos respondem segundo as normas do ECA, e não pelo Código Penal.','Criança: até 12 incompletos. Adolescente: 12 a 18. Pessoa idosa: 60 anos ou mais.',['ECA: menores de 18 anos','Idoso: 60 anos ou mais','proteção contra negligência']),
  GENERAL_STEP('hediondos','Alguns crimes têm tratamento legal mais rigoroso; o abuso de poder também é punido.','Hediondos e Abuso','A Lei 8.072/1990 lista os crimes hediondos, como o homicídio qualificado ou em atividade típica de grupo de extermínio, o estupro e a extorsão mediante sequestro.','Já a Lei 13.869/2019 pune o abuso de autoridade praticado por agente público com a finalidade específica de prejudicar outrem, beneficiar a si mesmo ou a terceiro, ou por mero capricho.','O cartão diferencia o rol taxativo da Lei 8.072/1990 e o dolo específico da Lei 13.869/2019.','Crime hediondo','Crime expressamente previsto no rol da Lei 8.072/1990, sujeito a regras penais e processuais mais gravosas.','Homicídio simples, em regra, não é hediondo, salvo quando praticado em atividade típica de grupo de extermínio.',['Lei 8.072: rol legal','Lei 13.869: abuso de autoridade','Lei 9.455: crime de tortura']),
  GENERAL_STEP('transito','Armas e trânsito seguem competências e autorizações definidas em lei.','Armas e Trânsito','A Lei 10.826/2003 diferencia posse irregular no interior da residência ou trabalho (titular do local) de porte ilegal fora deles. O CTB (Lei 9.503/1997) define as competências municipais de trânsito.','Aos órgãos executivos de trânsito dos municípios compete, na sua circunscrição, implantar, manter e operar o sistema de sinalização, dispositivos e equipamentos de controle viário.','O cartão compara posse vs. porte de arma e destaca a atuação municipal no trânsito.','Circunscrição municipal','O âmbito territorial em que o órgão executivo municipal de trânsito exerce suas competências previstas no art. 24 do CTB.','Posse refere-se à guarda no domicílio ou trabalho (pelo responsável legal); porte envolve circular fora deles.',['posse × porte (Lei 10.826)','drogas (Lei 11.343)','trânsito municipal (art. 24 CTB)'])
 ]},
 {id:'ingles_leitura',name:'Inglês: leitura de textos',label:'Línguas desde o começo',color:'#46739b',light:'#e6f0f9',symbol:'message',hero:'Ler em inglês em concursos começa pelo contexto e pelas conexões.',description:'Aprenda a identificar o assunto, reconhecer palavras próximas do português e evitar falsos amigos.',root:['Inglês para leitura','contexto, cognatos e conectivos'],steps:[
  GENERAL_STEP('contexto','Olhe primeiro o título, a fonte e o assunto geral.','Visão geral','Um texto sobre “Cloud computing and data security” já indica pelo título que trata de computação em nuvem e segurança de dados.','Você não precisa traduzir cada palavra isolada antes de entender o tema. Observe título, subtítulo, números, datas e palavras repetidas.','O cartão mostra como o tema geral aparece antes da tradução palavra por palavra.','Skimming e scanning','Estratégias de leitura para identificar a ideia geral do texto (skimming) ou localizar uma informação específica (scanning).','Primeiro encontre o assunto e o que o enunciado pergunta.',['título e fonte','palavras repetidas','localizar o trecho pedido']),
  GENERAL_STEP('cognatos','Muitas palavras parecem com o português; algumas enganam.','Cognatos e falsos amigos','Palavras como information, system e public têm sentido próximo ao português. Mas pretend significa fingir, e não pretender.','Cognatos verdadeiros ajudam muito na leitura técnica. Já os falsos cognatos (false friends), como actually (na verdade) e library (biblioteca), exigem atenção ao contexto.','O cartão compara cognatos transparentes com falsos amigos frequentes em provas.','Falso cognato','Palavra que se parece na forma com outra de nosso idioma, mas possui significado diferente.','Actually = na verdade. Pretend = fingir. Library = biblioteca.',['system → sistema','actually → na verdade','pretend → fingir']),
  GENERAL_STEP('pronomes','Pronomes em inglês retomam termos já citados.','Quem é it ou they?','Na frase “The system stores the file. It can print 20 pages”, o pronome It retoma The system.','Questões de prova frequentemente perguntam a que se referem pronomes como it (singular para coisa/sistema), they/them (plural), this, that, which ou who.','O cartão mostra a seta voltando do pronome para o termo antecedente.','Referência pronominal','A relação entre um pronome (como it, they, which) e o substantivo ou ideia que ele retoma no texto.','Volte à frase anterior e confira se o termo é singular, plural, pessoa ou objeto.',['it → coisa ou sistema (singular)','they / their → plural','who → pessoas · which → coisas']),
  GENERAL_STEP('conectivos','Conectivos mostram se a frase concorda, contrasta ou conclui.','However e therefore','“The tool is fast; however, it requires training.” A palavra however indica contraste, assim como “porém” em português.','Conhecer os conectivos ajuda a responder perguntas sobre a relação entre ideias: however, although e but indicam oposição; therefore e thus indicam conclusão; because e since podem indicar causa.','O cartão agrupa conectivos por função no texto.','Discourse markers','Conectivos que organizam a relação lógica entre frases, como oposição, causa, condição ou conclusão.','However / although = contraste. Therefore / thus = conclusão.',['however / although → contraste','therefore / thus → conclusão','moreover / in addition → adição']),
  GENERAL_STEP('tecnico','No contexto técnico, observe os modificadores e sufixos.','Termos no contexto','Na expressão “non-hackable system”, o prefixo non- nega e o sufixo -able indica possibilidade: algo que não pode ser invadido.','Em inglês, os adjetivos costumam vir antes do substantivo (“public service”, “digital security”). Observar prefixos (un-, non-, re-) e sufixos (-able, -less, -er) ajuda a deduzir o sentido.','O cartão decompõe prefixo, radical e sufixo de uma palavra do texto.','Afixos em inglês','Prefixos e sufixos que modificam o sentido ou a classe da palavra, como non-, un-, -able, -less e -er.','Em inglês, a característica costuma vir antes do nome principal.',['non- (não) + hack + -able (capaz)','= que não pode ser invadido','digital security → segurança digital'])
 ]},
 {id:'etica_servico',name:'Ética, controle e cidadania',label:'Administração e Estado desde o começo',color:'#6b609b',light:'#edeaf8',symbol:'plan',hero:'Servir ao público exige integridade, transparência e decisão baseada em evidências.',description:'Entenda ética pública, conflito de interesses, licitações, auditoria governamental e políticas públicas.',root:['Ética e controle','integridade, transparência e valor público'],steps:[
  GENERAL_STEP('etica','A função pública existe para atender ao interesse coletivo.','Ética pública','No serviço público, a conduta profissional deve unir legalidade, honestidade, cortesia, transparência e respeito ao cidadão.','A ética na administração pública não trata apenas de regras formais: exige distinguir o bem público do patrimônio privado e preservar a confiança social nas instituições.','O cartão destaca os deveres de probidade, transparência e respeito no atendimento.','Ética pública','Conjunto de princípios, valores e deveres que orientam a conduta de agentes públicos em favor do interesse coletivo.','Patrimônio e informação públicos não são propriedade pessoal do agente.',['interesse público','probidade e cortesia','respeito ao cidadão']),
  GENERAL_STEP('conflito','Um interesse particular não deve comprometer a decisão pública.','Conflito de interesses','Se um servidor precisa fiscalizar uma empresa da qual um familiar próximo é sócio, há risco de conflito entre o dever público e o interesse privado.','Prevenir conflitos de interesses envolve transparência, declaração de impedimento ou suspeição quando cabível e recusa de vantagens indevidas.','O cartão mostra a separação entre interesse particular e decisão institucional.','Conflito de interesses','Situação gerada pelo confronto entre interesses públicos e privados, que possa comprometer o interesse coletivo ou influenciar indevidamente o desempenho da função.','Diante de impedimento, declare a situação e afaste-se da decisão conforme a lei.',['dever público × interesse privado','declarar impedimento','recusar vantagens indevidas']),
  GENERAL_STEP('licitacoes','Contratar com recursos públicos exige planejamento e regras claras.','Licitações e contratos','Antes de comprar equipamentos ou contratar serviços, o órgão público planeja a necessidade e realiza licitação, salvo nas hipóteses legais de contratação direta.','A Lei 14.133/2021 disciplina licitações e contratos administrativos, buscando seleção da proposta apta a gerar o resultado mais vantajoso, tratamento isonômico e desenvolvimento nacional sustentável.','O cartão apresenta o fluxo básico: planejar, licitar, contratar e fiscalizar.','Licitação','Processo administrativo formal para selecionar propostas e celebrar contratos na administração pública, assegurando isonomia e transparência.','Toda contratação exige planejamento e fiscalização da entrega, inclusive nas hipóteses de dispensa ou inexigibilidade.',['1 · planejar a necessidade','2 · selecionar com isonomia','3 · fiscalizar o contrato']),
  GENERAL_STEP('auditoria','Auditar é comparar a situação encontrada com um critério confiável.','Auditoria e controle','Para avaliar um programa público, a equipe de auditoria coleta evidências, compara o que ocorreu com a norma aplicável e comunica conclusões e recomendações.','O controle na administração pública envolve controle interno (do próprio Poder), controle externo (exercido pelo Legislativo com auxílio dos Tribunais de Contas) e controle social pelos cidadãos.','O cartão relaciona critério, evidência e conclusão no trabalho de auditoria.','Evidência de auditoria','Informação relevante, confiável e suficiente utilizada pelo auditor para fundamentar suas conclusões.','Sem evidência verificável e critério claro, uma opinião isolada não constitui achado de auditoria.',['critério: o que deveria ser','evidência: o que foi verificado','conclusão e recomendação']),
  GENERAL_STEP('sociedade','Políticas públicas articulam Estado, orçamento e direitos na sociedade.','Estado e políticas','Para reduzir desigualdades ou melhorar um serviço, o Estado diagnostica o problema usando indicadores, desenha uma política pública, executa ações e avalia os resultados.','Compreender a formação social brasileira, o federalismo, a participação cidadã e os indicadores socioeconômicos ajuda a analisar se uma ação pública gera valor efetivo para a população.','O cartão resume o ciclo de políticas públicas: agenda, formulação, implementação e avaliação.','Política pública','Conjunto de decisões, programas e ações coordenados pelo Estado, com participação social, para enfrentar problemas coletivos e assegurar direitos.','Indicadores ajudam a diagnosticar desigualdades e avaliar se a política alcançou quem precisa.',['diagnóstico e indicadores','formulação e orçamento','implementação e avaliação'])
 ]},
 {id:'afo_orcamento',name:'Orçamento público e finanças',label:'Administração e finanças desde o começo',color:'#3d7a68',light:'#e3f3ed',symbol:'chart',hero:'Todo gasto público precisa estar previsto em lei e seguir etapas rigorosas.',description:'Entenda o ciclo PPA, LDO e LOA, os estágios da receita e da despesa e a Lei de Responsabilidade Fiscal.',root:['Orçamento público','planejar, autorizar e prestar contas'],steps:[
  GENERAL_STEP('instrumentos','Três leis conectam o planejamento de médio prazo ao orçamento de cada ano.','PPA, LDO e LOA','Primeiro o governo planeja quatro anos no PPA, depois define metas e prioridades do ano seguinte na LDO e, por fim, estima receitas e fixa despesas na LOA.','Na Constituição (art. 165), o Plano Plurianual (PPA) estabelece diretrizes, objetivos e metas de 4 anos; a Lei de Diretrizes Orçamentárias (LDO) orienta a elaboração do orçamento anual; a Lei Orçamentária Anual (LOA) detalha receitas e despesas do exercício.','O cartão mostra a ponte: PPA (4 anos) → LDO (metas e regras) → LOA (orçamento do ano).','Ciclo orçamentário','A articulação constitucional entre PPA, LDO e LOA para planejar, orientar e executar o orçamento público.','PPA: 4 anos. LDO: metas e prioridades. LOA: estima a receita e fixa a despesa.',['PPA: 4 anos (diretrizes e metas)','LDO: prioridades e metas fiscais','LOA: orçamento anual detalhado']),
  GENERAL_STEP('principios','O orçamento reúne todas as receitas e despesas em um quadro transparente.','Princípios orçamentários','Para evitar gastos ocultos, a LOA deve conter todas as receitas e despesas pelos seus valores brutos, valendo para o período de um ano.','Os princípios clássicos incluem anualidade (um exercício financeiro), universalidade (todas as receitas e despesas), orçamento bruto (sem deduções prévias) e exclusividade (a LOA não contém matéria estranha à previsão da receita e fixação da despesa, salvo autorização para créditos suplementares e operações de crédito por ARO).','O cartão destaca universalidade, anualidade e as duas exceções da exclusividade.','Exclusividade orçamentária','Princípio do art. 165, § 8º, da CF/88 segundo o qual a LOA só trata de receita e despesa, ressalvados créditos suplementares e ARO.','A LOA não pode conter "caudas orçamentárias" estranhas às finanças públicas.',['universalidade e anualidade','orçamento bruto (sem descontos)','exclusividade + 2 exceções']),
  GENERAL_STEP('receita','A receita pública percorre etapas desde a previsão até a entrada no caixa.','Estágios da receita','Quando o orçamento é aprovado, a receita está prevista; depois o fisco calcula quem deve pagar (lançamento), o cidadão paga (arrecadação) e o valor entra na conta única (recolhimento).','Pela Lei 4.320/1964 e manuais de contabilidade pública, a execução da receita envolve lançamento (ato que identifica o devedor e o valor), arrecadação (pagamento pelos contribuintes aos agentes arrecadadores) e recolhimento (transferência ao Tesouro).','O cartão diferencia arrecadação no banco de recolhimento à Conta Única do Tesouro.','Estágios da receita','Sequência de previsão, lançamento, arrecadação e recolhimento dos recursos públicos ao Tesouro.','Arrecadar é receber do contribuinte; recolher é entregar o valor ao Tesouro.',['1 · previsão na LOA','2 · lançamento · 3 · arrecadação','4 · recolhimento ao Tesouro']),
  GENERAL_STEP('despesa','Nenhum pagamento público ocorre sem antes reservar o valor e conferir a entrega.','Empenho, liquidação e pagamento','Antes de pagar um fornecedor, o órgão reserva a dotação (empenho), confere se o produto ou serviço foi entregue (liquidação) e só então transfere o dinheiro (pagamento).','Na Lei 4.320/1964 (arts. 58 a 65), a execução da despesa segue três estágios obrigatórios: empenho (reserva do crédito), liquidação (verificação do direito adquirido pelo credor mediante títulos e documentos comprobatórios) e pagamento.','O cartão mostra a ordem imutável: Empenho → Liquidação → Pagamento.','Estágios da despesa','As três fases da execução da despesa orçamentária segundo a Lei 4.320/1964: empenho, liquidação e pagamento.','Nunca se paga sem antes liquidar (verificar que o bem ou serviço foi efetivamente prestado).',['1º · Empenho (reserva o valor)','2º · Liquidação (confere a entrega)','3º · Pagamento (quita a obrigação)']),
  GENERAL_STEP('lrf','A gestão fiscal responsável exige equilíbrio, metas e limites para despesas.','Responsabilidade Fiscal','A Lei Complementar 101/2000 (LRF) fixa limites para despesa com pessoal e exige reserva de contingência para riscos fiscais imprevistos.','A LRF estabelece normas de finanças públicas voltadas para a responsabilidade na gestão fiscal: planejamento, transparência, controle de limites de despesa com pessoal (ex.: 50% da RCL na União; 60% em Estados e Municípios) e de dívida.','O cartão mostra o equilíbrio entre receitas e despesas e a reserva para passivos contingentes.','Reserva de contingência','Dotação global na LOA, definida com base na RCL pela LDO, destinada ao atendimento de passivos contingentes e outros riscos e eventos fiscais imprevistos.','Reserva de contingência atende riscos e eventos fiscais imprevistos (art. 5º, III, da LRF).',['metas fiscais e transparência','limites de despesa com pessoal','reserva de contingência (LRF)'])
 ]}
);
